// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Rus, Fransız ve İngiliz edebiyatı klasikleri (orta).
const ozLiterature10Orta = <(String, String, List<String>, String)>[
  ('Puşkin\'in Pugaçov ayaklanması sırasında genç subay Pyotr Grinyov\'un yaşadıklarını anlattığı tarihî romanı hangisidir?', 'Kaptanın Kızı', ['Maça Kızı', 'Dubrovski adlı soylu eşkıya', 'Bronz Süvari'], 'Kaptanın Kızı (1836), 1773-1775 Pugaçov ayaklanmasını Grinyov\'un anıları biçiminde anlatır. Maça Kızı bir öyküdür; Bronz Süvari ise manzum bir anlatıdır.'),
  ('Yevgeni Onegin\'de Onegin\'in en yakın dostu olan genç şair Lenski\'nin sonu nasıl olur?', 'Onegin\'le yaptığı düelloda ölür', ['Kafkasya\'da savaşırken ölür', 'Olga ile evlenip köyüne yerleşir', 'Sürgüne gönderilip Sibirya\'da kaybolur'], 'Onegin, Lenski\'nin nişanlısı Olga ile flört edince düello çıkar ve Onegin, Lenski\'yi öldürür. Bu olay, ozanın kendi ölümünü de sezdirir gibi okunur.'),
  ('Puşkin\'in kıskançlıktan Mozart\'ı zehirleyen bir besteciyi konu alan kısa trajedisi hangisidir?', 'Mozart ve Salieri', ['Taş Konuk', 'Cimri Şövalye', 'Veba Zamanında Şölen'], 'Puşkin\'in \'Küçük Trajediler\' dizisinden olan Mozart ve Salieri, dâhiye duyulan kıskançlığı işler; olay tarihsel olarak kanıtlanmış değildir, efsaneye dayanır.'),
  ('Puşkin\'in Sahte Dimitri\'nin tahta yürümesini işleyen ve Mussorgski\'nin operasına kaynaklık eden tarihî dram hangisidir?', 'Boris Godunov', ['Poltava', 'Kafkas Tutsağı', 'Çingeneler'], 'Boris Godunov, Karışıklık Dönemi\'nde çarın meşruiyetini ve halkın sessiz gücünü işler; Mussorgski bu metinden operasını bestelemiştir.'),
  ('Lermontov\'un \'Zamanımızın Bir Kahramanı\' romanının yapısı için hangisi doğrudur?', 'Birbirine bağlı beş öyküden ve Peçorin\'in günlüğünden oluşur', ['Tek bir anlatıcının kronolojik sırayla aktardığı bir romandır', 'Mektuplardan oluşan bir aşk romanıdır', 'Manzum kıtalarla yazılmış bir destandır'], 'Roman \'Bela\', \'Maksim Maksimiç\', \'Taman\', \'Prenses Meri\' ve \'Kaderci\' bölümlerinden oluşur; olaylar kronolojik sırada verilmez ve farklı anlatıcılar kullanılır.'),
  ('Lermontov\'u 1837\'de Kafkasya\'ya sürgüne gönderilmesine yol açan şiiri hangisidir?', 'Şairin Ölümü', ['Yelken ve Dalgalar Üstüne', 'İblis', 'Borodino'], 'Puşkin\'in düelloda ölümü üzerine yazdığı \'Şairin Ölümü\', saray çevresini suçladığı için Lermontov\'un sürgün edilmesine neden olmuştur.'),
  ('Gürcü prensesi Tamara\'ya âşık olan düşmüş bir meleği anlatan Lermontov poeması hangisidir?', 'İblis', ['Mtsıri', 'Maskeli Balo', 'Hacı Abrek'], 'Lermontov\'un \'İblis\' (Demon) poeması Kafkasya\'da geçer; sonsuz yalnızlık içindeki iblisin Tamara\'ya aşkını işler.'),
  ('Lermontov ile Puşkin\'in yaşamları karşılaştırıldığında aralarındaki farklardan biri hangisidir?', 'Lermontov düelloda 26 yaşında, Puşkin ise 37 yaşında ölmüştür', ['Lermontov şiir yazmamış, yalnız roman yazmıştır', 'Puşkin Kafkasya\'yı hiç görmemiş, Lermontov oraya hiç sürülmemiştir', 'Lermontov Puşkin\'den bir kuşak önce doğmuştur'], 'Puşkin 1837\'de 37 yaşında, Lermontov 1841\'de 26 yaşında düelloda ölmüştür; ikisi de şiir ve düzyazı vermiş, ikisi de Kafkasya\'da bulunmuştur.'),
  ('Gogol\'ün arı yetiştiricisi Rudi Panko\'nun anlattığı Ukrayna halk öykülerinden oluşan ilk büyük kitabı hangisidir?', 'Dikanka Yakınlarında Bir Çiftlikte Akşamlar', ['Petersburg Öyküleri', 'Mirgorod', 'Seçilmiş Dostlarla Yazışmalardan Parçalar'], '1831-1832\'de yayımlanan bu kitap, Ukrayna köy yaşamını, büyü ve cin öykülerini mizahla birleştirir ve Gogol\'ü üne kavuşturur.'),
  ('Gogol\'ün \'Taras Bulba\' anlatısında yaşlı Kazak önderi Taras\'ın oğlu Andriy\'i öldürmesinin nedeni nedir?', 'Bir Polonyalı kıza duyduğu aşk yüzünden Kazaklara ihanet etmesi', ['Babasının yerine önder olmak için Kazaklara karşı açıkça ayaklanması', 'Kardeşi Ostap\'ı düşmana teslim etmesi', 'Ortodoks inancını bırakıp manastıra kapanması'], 'Andriy, kuşatılan kentteki Polonyalı soylu kız için saf değiştirir; Taras \'Seni ben doğurttum, ben de öldüreceğim\' diyerek onu öldürür.'),
  ('Gogol\'ün \'Bir Delinin Hatıra Defteri\' öyküsünde küçük memur Poprişçin sonunda kendini kim sanmaya başlar?', 'İspanya kralı', ['Bütün Rusların çarı', 'Napolyon', 'Papa'], 'Poprişçin köpeklerin mektuplaştığını düşünür, sonra İspanya tahtının boş olduğunu ve kralın kendisi olduğunu sanır; öykü bir akıl hastanesinde biter.'),
  ('Gogol\'ün \'Müfettiş\' oyununda sahte müfettiş sanılan genç memurun adı nedir?', 'Hlestakov', ['Pavel İvanoviç Çiçikov', 'Sobakeviç', 'Manilov'], 'Hlestakov, kasabada yüksek bir yetkili sanılır; Çiçikov, Sobakeviç ve Manilov ise Ölü Canlar\'ın kişileridir.'),
  ('Gogol\'ün Ölü Canlar\'ın ikinci cildiyle ilgili olarak yaptığı ünlü davranış nedir?', 'Ölümünden kısa süre önce elyazmasının büyük bölümünü yakması', ['İkinci cildi Fransızca yazıp Paris\'te bir yayıncıya bastırması ve Rusya\'da yasaklatması', 'İkinci cildi tiyatro oyununa çevirmesi', 'İkinci cildin yazımını Turgenyev\'e bırakması'], 'Gogol, 1852\'de dinsel bir bunalım içinde ikinci cildin elyazmalarını yakmış, birkaç gün sonra ölmüştür; yalnız bazı bölümler kalmıştır.'),
  ('Moskova sosyetesinin ikiyüzlülüğünü yurt dışından dönen genç Çatski\'nin gözünden hicveden manzum komedya hangisidir?', 'Akıllılık Belası', ['Müfettiş', 'Köyde Bir Ay', 'Gelinin Çeyizi Olmayan Kız'], 'Griboyedov\'un \'Akıllılık Belası\' (1824), Famusov\'un evinde geçer; dizeleri Rusçada atasözü gibi yerleşmiştir.'),
  ('Köylü kızın soylu bir gence kandırılıp kendini göle atmasını anlatan ve Rus duygusalcılığının (sentimantalizm) simgesi olan öykü hangisidir?', 'Karamzin\'in \'Zavallı Liza\'sı', ['Puşkin\'in \'İstasyon Şefi\' adlı öyküsü', 'Turgenyev\'in \'Asya\'sı', 'Leskov\'un \'Solak\'ı'], 'Nikolay Karamzin\'in 1792 tarihli \'Zavallı Liza\'sı, \'köylü kadınlar da sevmeyi bilir\' düşüncesiyle Rus duygusalcılığının en ünlü örneği olmuştur.'),
  ('Turgenyev\'in \'İlk Aşk\' adlı uzun öyküsünde genç Vladimir\'in âşık olduğu Zinaida\'nın sırrı nedir?', 'Vladimir\'in babasıyla gizli bir ilişki yaşaması', ['Aslında gizli bir devrimci örgütün üyesi olup polisçe aranması', 'Vladimir\'in kayıp ablası çıkması', 'Bir prensle gizlice evlenmiş olması'], 'Vladimir, sonunda Zinaida\'nın kendi babasının sevgilisi olduğunu fark eder; öykü Turgenyev\'in kendi gençlik anılarından izler taşır.'),
  ('Babalar ve Oğullar\'ın sonunda Bazarov\'un ölümüne yol açan olay nedir?', 'Bir kadavrayı incelerken parmağını kesip tifüse yakalanması', ['Pavel Petroviç ile yaptığı düelloda göğsünden vurulması', 'Tutuklanıp hapishanede verem olması', 'Odintsova\'nın reddi üzerine intihar etmesi'], 'Bazarov, tifüsten ölen bir köylünün cesedini incelerken kendini keser ve enfeksiyon kapar; düelloda ise Pavel Petroviç yaralanmıştır.'),
  ('Turgenyev\'in \'Mumu\' öyküsünde sağır ve dilsiz uşak Gerasim\'in köpeğini boğmak zorunda kalması hangi düzeni eleştirir?', 'Toprak sahibinin serfler üzerindeki keyfî ve sınırsız gücünü', ['Kentte yükselen tüccar sınıfının açgözlülüğünü ve ahlaksızlığını', 'Kilisenin köylüler üzerindeki baskısını', 'Ordudaki katı disiplin ve rütbe düzenini'], 'Gerasim, hanımefendinin buyruğuyla sevdiği köpeği boğar; öykü serfliğin insanlık dışı yüzünü sade bir dille gösterir.'),
  ('Turgenyev\'in Avrupa\'yla bağlarını en iyi gösteren durum hangisidir?', 'Uzun yıllar Fransa\'da yaşayıp Flaubert ve Zola gibi yazarlarla dostluk kurması', ['Yalnızca Fransızca yazıp Rusça hiçbir eser vermemesi', 'İngiliz parlamentosuna seçilmesi', 'Romanlarının tümünü Paris\'te geçirmesi'], 'Turgenyev, şarkıcı Pauline Viardot\'nun çevresinde Fransa\'da yaşamış, Flaubert ile yakın dost olmuş ve Rus edebiyatını Batı\'ya tanıtmıştır.'),
  ('Oblomov romanında tembel kahramanın tam karşıtı olarak çizilen, çalışkan ve girişimci arkadaşı kimdir?', 'Stolz', ['Zahar', 'Tarantyev', 'Volkov'], 'Alman-Rus kökenli Andrey Stolz, düzenli ve eylemci kişiliğiyle Oblomov\'un karşıtıdır; Zahar ise Oblomov\'un uşağıdır.'),
  ('Oblomov\'un Olga ile yaşadığı aşkın sona ermesinin temel nedeni hangisidir?', 'Oblomov\'un evliliğin gerektirdiği sorumluluk ve eylemden kaçması', ['Olga\'nın Oblomov\'u başka bir adam için aldatması', 'Olga\'nın ailesinin Oblomov\'un yoksulluğunu ve soyunu bahane etmesi', 'Oblomov\'un savaşa gönderilmesi'], 'Olga, Oblomov\'u harekete geçirmeye çalışır; ama Oblomov sürekli erteleyip kararsız kalınca ilişki biter. Olga sonra Stolz ile evlenir.'),
  ('Suç ve Ceza\'da Raskolnikov\'u doğrudan kanıt göstermeden psikolojik baskıyla itirafa yaklaştıran sorgu yargıcı kimdir?', 'Porfiri Petroviç', ['Dmitri Razumihin', 'Svidrigaylov', 'Lujin'], 'Porfiri Petroviç, Raskolnikov\'un yazdığı makaleyi bilir ve onunla kedi-fare oyunu oynar; Razumihin ise Raskolnikov\'un dostudur.'),
  ('Suç ve Ceza\'da Raskolnikov\'un en yakın dostu olan ve sonunda kız kardeşi Dunya ile evlenen öğrenci kimdir?', 'Razumihin', ['Zametov', 'Lebezyatnikov', 'Pyotr Petroviç Lujin'], 'Neşeli ve dürüst öğrenci Razumihin, hasta Raskolnikov\'a bakar, ailesine destek olur ve sonunda Dunya ile evlenir.'),
  ('Suç ve Ceza\'da Raskolnikov tefeci kadının yanı sıra planında olmayan ikinci bir kişiyi de öldürür. Bu kişi kimdir?', 'Tefecinin üvey kız kardeşi Lizaveta', ['Sonya\'nın babası Marmeladov', 'Raskolnikov\'un kaldığı odanın ev sahibesi', 'Kız kardeşi Dunya\'nın nişanlısı'], 'Cinayet sırasında içeri giren uysal Lizaveta\'yı da öldürmesi, Raskolnikov\'un \'ilkeli suç\' kuramını daha baştan çürütür.'),
  ('Suç ve Ceza\'da Sonya\'nın Raskolnikov\'a İncil\'den okuduğu ve onun yeniden doğuşunu simgeleyen öykü hangisidir?', 'Lazarus\'un diriltilmesi', ['Kayıp oğulun dönüşü', 'Yunus\'un balığın karnında kalması', 'Kabil\'in Habil\'i öldürmesi'], 'Sonya\'nın okuduğu Lazarus öyküsü, ölümden diriliş temasıyla Raskolnikov\'un ahlaki dirilişini önceden simgeler.'),
  ('Karamazov Kardeşler\'in yargılama bölümünde babasını öldürmekle suçlanan kardeş hangisidir ve sonuç ne olur?', 'Dmitri; suçsuz olduğu hâlde mahkûm edilir', ['İvan; delilik gerekçesiyle sorumsuz bulunarak aklanır', 'Alyoşa; tanıklıkla kurtulur', 'Dmitri; jüri onu oy birliğiyle aklar'], 'Kanıtlar Dmitri\'yi gösterdiği için jüri onu suçlu bulur; oysa asıl katil Smerdyakov\'dur.'),
  ('Dostoyevski\'nin Omsk\'taki kürek cezası yıllarını kurgusal bir anlatıcı aracılığıyla anlattığı eseri hangisidir?', 'Ölüler Evinden Anılar', ['Yeraltından Notlar', 'Bir Yazarın Günlüğü\'nden Seçmeler', 'Ezilenler'], 'Ölüler Evinden Anılar, karısını öldürmüş Goryançikov\'un notları biçiminde Sibirya hapishanesindeki yaşamı anlatır; Tolstoy bu eseri çok beğenmiştir.'),
  ('Dostoyevski\'nin \'Öteki\' (Dvoynik) adlı romanında memur Golyadkin\'in yaşadığı tuhaf durum nedir?', 'Kendisine tıpatıp benzeyen ve onun yerini almaya başlayan bir adamla karşılaşması', ['Bir sabah kendini böceğe dönüşmüş bulması', 'Bir sabah uyandığında burnunun yüzünden kaybolduğunu ve kentte dolaştığını görmesi', 'Ölü köylülerin kayıtlarını satın alması'], 'Golyadkin\'in ikizi, iş yerinde ve sosyetede onun yerini alır; roman, bölünmüş kimlik ve delilik temasını işler.'),
  ('Suç ve Ceza\'da arabanın altında kalarak ölen ve ailesini perişan bırakan içkici eski memur kimdir?', 'Marmeladov', ['Lebezyatnikov', 'Zametov', 'Lujin'], 'Marmeladov, meyhanedeki itirafıyla Raskolnikov\'un ailesine bağlanmasını sağlar; ölümü Sonya\'nın ailesini daha da yoksullaştırır.'),
  ('Bir öğrenci \'Dostoyevski romanlarında olaylar uzun yıllara yayılmaz, birkaç güne sıkışan krizlerle ilerler\' diyor. Bu gözlemi en iyi destekleyen örnek hangisidir?', 'Suç ve Ceza\'nın asıl bölümünün cinayetten itirafa kadar yaklaşık iki haftayı kapsaması', ['Savaş ve Barış\'ın 1805\'ten 1820\'ye uzanması', 'Oblomov\'un kahramanın bütün yaşamını anlatması', 'Babalar ve Oğullar\'ın bir sonsözle kahramanların yıllar sonraki yaşamına atlaması'], 'Suç ve Ceza\'nın altı bölümü kısa bir zaman dilimine sıkışmış yoğun bir krizi anlatır; diğer seçenekler başka yazarların uzun zamanlı yapısına örnektir.'),
  ('Savaş ve Barış\'ta Nataşa Rostova\'nın nişanlısı Andrey\'e karşı yaptığı ve sonradan derin pişmanlık duyduğu hata nedir?', 'Anatol Kuragin\'le kaçmaya kalkışması', ['Andrey\'in mektuplarını Pierre\'e okutması', 'Moskova\'dan ailesiyle birlikte kaçmaması', 'Andrey\'in babasına hakaret edip onu kızdırması'], 'Nataşa, evli olduğunu bilmediği çapkın Anatol\'a kapılarak kaçmayı planlar; plan son anda engellenir ve nişan bozulur.'),
  ('Anna Karenina romanı hangi karakterin evlilik içi sadakatsizliğinin yarattığı aile bunalımıyla açılır?', 'Anna\'nın ağabeyi Stepan Oblonski', ['Anna\'nın kocası, devlet görevlisi Aleksey Karenin', 'Kont Aleksey Vronski', 'Konstantin Levin'], 'Romanın başında Stiva Oblonski\'nin çocuklarının mürebbiyesiyle ilişkisi ortaya çıkar; Anna, ağabeyiyle eşini barıştırmak için Moskova\'ya gelir.'),
  ('Anna Karenina\'da Anna ile Vronski\'nin ilk karşılaştığı tren istasyonunda yaşanan ve romanın sonunu önceden sezdiren olay nedir?', 'Bir demiryolu işçisinin trenin altında kalarak ölmesi', ['Anna\'nın çantasının çalınması', 'Vronski\'nin annesinin bayılması', 'Trenin büyük bir kar fırtınası nedeniyle yolda kalması'], 'Anna bu ölümü \'kötü bir işaret\' olarak görür; roman, Anna\'nın kendini trenin altına atmasıyla bu ilk sahneye geri döner.'),
  ('Anna Karenina\'nın başına konan \'Öç benimdir, ben ödeyeceğim\' epigrafının kaynağı neresidir?', 'Kutsal Kitap', ['Shakespeare\'in Hamlet\'i', 'Puşkin\'in Yevgeni Onegin\'i', 'Homeros\'un İlyada\'sı'], 'Epigraf, Pavlus\'un Romalılara Mektup\'undan alınmıştır; yargılama hakkının insanlara değil Tanrı\'ya ait olduğunu ima eder.'),
  ('Tolstoy\'un, kıskançlıkla karısını öldüren Pozdnışev\'in bir tren yolculuğunda öyküsünü anlattığı ve adını bir Beethoven yapıtından alan uzun öyküsü hangisidir?', 'Kreutzer Sonatı', ['Aile Mutluluğu Üzerine', 'Şeytan', 'Peder Sergiy'], 'Kreutzer Sonatı, evlilik ve cinsellik üzerine sert görüşleri nedeniyle Rusya\'da bir süre yasaklanmıştır.'),
  ('Tolstoy\'un edebiyat dünyasına girdiği ilk yapıtlar hangi üçlemedir?', 'Çocukluk, İlkgençlik, Gençlik', ['Sivastopol Öyküleri, Kazaklar, Diriliş', 'Sabah, Öğle, Akşam', 'Babalar, Oğullar, Torunlar'], 'Tolstoy 1852\'de \'Çocukluk\' ile adını duyurmuş, ardından \'İlkgençlik\' ve \'Gençlik\' gelmiştir; yarı otobiyografik bir gelişim üçlemesidir.'),
  ('Tolstoy\'un Kırım Savaşı\'nda bizzat bulunduğu kuşatmayı anlattığı öykü dizisi hangisidir?', 'Sivastopol Öyküleri', ['Kafkasya\'dan Bir Tutsağın Anıları', 'Baskın', 'Ağaç Kesimi'], 'Topçu subayı olarak Sivastopol kuşatmasına katılan Tolstoy, savaşın gerçek yüzünü romantik kahramanlık anlayışından uzak bir gerçekçilikle anlatmıştır.'),
  ('Tolstoy\'un \'Efendi ile Uşağı\' öyküsünde kar fırtınasında yolunu kaybeden açgözlü tüccar Brehunov\'un son davranışı nedir?', 'Donmak üzere olan uşağı Nikita\'yı kendi bedeniyle ısıtıp kurtarır', ['Uşağını kar içinde bırakıp atla kaçar', 'Uşağına bütün servetini vasiyet edip kar içinde kendi canına kıyar', 'Uşağını suçlayıp onu mahkemeye verir'], 'Brehunov, ölümle yüz yüze geldiğinde Nikita\'nın üstüne kapanır; kendisi donarak ölür, Nikita kurtulur. Öykü ahlaki bir aydınlanmayı anlatır.'),
  ('Tolstoy\'un yaşamının sonuyla ilgili hangisi doğrudur?', '82 yaşında evini gizlice terk etmiş ve Astapovo tren istasyonunda ölmüştür', ['Yasnaya Polyana\'daki evinde, bütün ailesi ve dostları yanındayken sessizce ölmüştür', 'Sibirya\'ya sürgüne gönderilmiş ve orada ölmüştür', 'Paris\'te bir hastanede tedavi görürken ölmüştür'], 'Tolstoy Kasım 1910\'da yalın bir yaşam sürmek amacıyla evinden ayrılmış, yolda hastalanmış ve küçük Astapovo istasyonunun şef evinde ölmüştür.'),
  ('Bir öğrenci, Tolstoy\'un Savaş ve Barış\'ını elle defalarca temize çekerek yazarın en yakın yardımcısı olan kişiyi araştırıyor. Bu kişi kimdir?', 'Eşi Sofya Tolstaya', ['Kızı Aleksandra', 'Dostu Turgenyev', 'Yayıncısı Mihail Katkov'], 'Sofya Andreyevna Tolstaya, kocasının elyazmalarını gece gündüz kopyalamış, yayın işlerini yürütmüş ve günlükleriyle de önemli bir tanık olmuştur.'),
  ('Çehov\'un \'Martı\' oyununda bir martıyı vurup Nina\'nın ayaklarına bırakan, sonunda da kendi yaşamına son veren genç yazar kimdir?', 'Konstantin Treplev', ['Boris Trigorin', 'Pyotr Sorin', 'Doktor Yevgeni Dorn adlı hekim'], 'Treplev, annesi Arkadina\'nın ve ünlü yazar Trigorin\'in gölgesinde ezilen genç bir yazardır; oyun onun intiharıyla biter.'),
  ('Vanya Dayı\'da Vanya\'nın bunca yıl çiftliği yönetip parasını gönderdiği emekli profesöre karşı yaptığı patlama nedir?', 'Ona iki kez ateş eder ama ıskalar', ['Onu mahkemeye verip mirastan men ettirir', 'Onu evden kovup çiftliği kendi adına satar', 'Onun yazdığı kitabın taklit olduğunu gazetede açıklar'], 'Serebryakov\'un çiftliği satma önerisi üzerine öfkelenen Vanya ona tabancayla iki kez ateş eder ama vuramaz; bu da Çehov\'un acı-komik tavrını gösterir.'),
  ('Vanya Dayı\'nın sonunda Sonya\'nın \'Dinleneceğiz\' diye başlayan konuşması oyuna nasıl bir son kazandırır?', 'Hiçbir şeyin değişmediği sıradan yaşamı sabır ve umutla kabullenen hüzünlü bir son', ['Bütün kişilerin kente taşınıp yeni ve parlak bir yaşama başlamasıyla biten neşeli bir son', 'Vanya\'nın tutuklanmasıyla gerilimli bir son', 'Profesörün ölümüyle trajik bir son'], 'Profesör gittikten sonra Vanya ve Sonya eski işlerine dönerler; Sonya, öbür dünyada dinlenecekleri umuduyla dayısını teselli eder.'),
  ('Vişne Bahçesi\'nde aile malikânesini açık artırmada satın alan, babası ve dedesi o toprakların serfi olmuş tüccar kimdir?', 'Yermolay Lopahin', ['Öğrenci Pyotr Sergeyeviç Trofimov', 'Leonid Gayev', 'Semyon Yepihodov'], 'Lopahin\'in malikâneyi alması, serfliğin kalkmasından sonra yükselen yeni sınıfın eski soyluların yerini almasını somutlaştırır.'),
  ('Çehov\'un \'Bir Memurun Ölümü\' öyküsünde Çervyakov\'un sonunu getiren olay nedir?', 'Tiyatroda önündeki generalin üstüne hapşırıp defalarca özür dilemekten kendini yıpratması', ['Amirinin parasını kaybedip hapse girmesi', 'Generalin kızına âşık olup reddedilmesi', 'Rüşvet almakla suçlanıp işten atılması ve ardından bütün yakınlarının ondan yüz çevirmesi'], 'Çervyakov\'un aşırı korkusu ve yaltaklanması, onu küçük bir olaydan dolayı ölüme sürükler; öykü bürokratik korkuyu hicveder.'),
  ('Çehov\'un her türlü yenilikten korkan, şemsiyesini, saatini, hatta düşüncelerini \'kılıf içinde\' tutan öğretmen Belikov\'u anlattığı öyküsü hangisidir?', 'Kılıf İçindeki Adam', ['Bektaşi Üzümü Bahçesi', 'Aşk Üzerine', 'Ionıç'], 'Belikov, \'bir şey olmasın\' kaygısıyla yaşayan, çevresini de baskı altında tutan bir tiptir; öykü Çehov\'un üçlemesinin ilk halkasıdır.'),
  ('Çehov\'un \'Vanka\' öyküsünde dokuz yaşındaki çırak Vanka\'nın mektubunun okura derin bir hüzün vermesinin nedeni nedir?', 'Zarfa yalnız \'Köydeki dedeme\' yazdığı için mektubun hiçbir zaman ulaşmayacak olması', ['Mektubun dedesinin ölümünden sonra ulaşacak olması', 'Vanka\'nın okuma yazma bilmediği için dedesine bomboş bir kâğıt göndermiş olduğunun anlaşılması', 'Mektubun ustası tarafından okunup yırtılması'], 'Vanka, ustasının kötü davranışlarından kurtulmak için dedesine yalvarır ama adres yazmadığından mektup ulaşmayacaktır; okur bunu bilir, Vanka bilmez.'),
  ('Çehov\'un yaşamının son yıllarıyla ilgili hangisi doğrudur?', '1904\'te Almanya\'da veremden ölmüş, oyuncu Olga Knipper ile evlenmiştir', ['Sibirya\'da sürgündeyken ölmüş ve hiç evlenmemiştir', 'Paris\'te sürgündeyken ölmüş, bir şarkıcıyla evlenmiştir', 'Yalta\'da bir düelloda ölmüş, bir prensesle evlenmiştir'], 'Çehov 1901\'de oyuncu Olga Knipper ile evlenmiş, verem nedeniyle Badenweiler\'e gitmiş ve 1904\'te orada ölmüştür.'),
  ('Bir yazarlık atölyesinde öğrencilere \'sonucu söyleme, okuru yargılamaya zorlama; durumu doğru göster, gerisini okur tamamlasın\' öğüdü veriliyor. Bu yaklaşıma en uygun yazar örneği hangisidir?', 'Çehov\'un açık uçlu, yargısız öyküleri', ['Zola\'nın kalıtım kuramını kanıtlamaya çalışan romanları', 'Tolstoy\'un son dönemindeki öğretici halk öyküleri', 'Dickens\'ın iyileri ödüllendiren mutlu sonlu romanları'], 'Çehov, yazarın görevinin soruyu doğru koymak olduğunu, yanıtlamanın okura düştüğünü söylemiştir; öyküleri çoğu zaman açık uçlu biter.'),
  ('Ostrovski\'nin \'Fırtına\' oyununda baskıcı kaynanası Kabanova\'nın evinde bunalan Katerina\'nın sonu nasıl olur?', 'Kendini Volga\'ya atar', ['Kocasıyla Moskova\'ya kaçar ve orada yeni bir yaşam kurar', 'Manastıra kapanır', 'Kaynanasını zehirler ve tutuklanır'], 'Yasak aşkını itiraf eden Katerina, çevresinin baskısına dayanamayıp nehre atlar; Dobrolyubov onu \'karanlık krallıkta bir ışık ışını\' diye yorumlamıştır.'),
  ('Ostrovski\'nin oyunlarının büyük bölümünde konu edindiği toplumsal kesim hangisidir?', 'Moskova\'nın tüccar sınıfı', ['Petersburg sarayındaki soylular ve onların yabancı mürebbiyeleri', 'Sibirya\'daki sürgünler', 'Kafkasya\'daki subaylar'], 'Ostrovski, Moskova tüccarlarının kapalı, ataerkil ve paraya dayalı dünyasını sahneye taşımış, Rus ulusal tiyatrosunun kurucularından sayılmıştır.'),
  ('Leskov\'un, tutkusu uğruna cinayetler işleyen taşralı bir tüccar karısını anlatan ve Şostakoviç\'in operasına kaynaklık eden uzun öyküsünün adında hangi Shakespeare karakterine gönderme vardır?', 'Lady Macbeth', ['Ofelya', 'Desdemona', 'Mısır kraliçesi Kleopatra'], '\'Mtsensk İlçesinin Lady Macbeth\'i\' Katerina İzmaylova\'nın kanlı tutkusunu anlatır; başlık, Shakespeare\'in hırslı ve suç ortağı kadın kahramanına göndermedir.'),
  ('Nekrasov\'un \'Rusya\'da Kim Mutlu Yaşar?\' adlı uzun şiirinin çerçevesi nedir?', 'Yedi köylünün Rusya\'da gerçekten mutlu olan birini aramak için yola çıkması', ['Bir çarın kılık değiştirip halkın arasına karışması ve köy köy dolaşıp yoksulların dertlerini dinlemesi', 'Bir şairin Kafkasya\'dan Moskova\'ya yaptığı yolculuk', 'Bir rahibin köy köy gezip günah çıkarması'], 'Serfliğin kaldırılmasından sonra yazılan poemada köylüler toprak sahibine, rahibe, tüccara ve çara kadar herkese mutlu olup olmadığını sorarlar.'),
  ('Maksim Gorki adıyla ilgili hangisi doğrudur?', 'Gerçek adı Aleksey Peşkov\'dur; \'Gorki\' Rusçada \'acı\' anlamına gelir', ['Gerçek adı Lev Bronştayn\'dır; \'Gorki\' sözcüğü Rusçada \'dağlı\' ya da \'tepeli\' anlamındadır', 'Gorki onun gerçek soyadıdır ve soylu bir aileden gelir', 'Gerçek adı İvan Bunin\'dir; \'Gorki\' doğduğu köyün adıdır'], 'Aleksey Maksimoviç Peşkov, yaşadığı yoksul ve sert hayatı çağrıştıran \'acı\' anlamlı Gorki takma adını seçmiştir.'),
  ('Gorki\'nin \'Ana\' romanında işçi Pavel Vlasov\'un annesi Pelageya Nilovna\'nın geçirdiği dönüşüm nedir?', 'Korkak ve ezilmiş bir kadınken oğlunun davasını benimseyip bildiri dağıtan bir devrimciye dönüşmesi', ['Varlıklı bir tüccarla evlenip sınıf atlaması', 'Oğlunu polise ihbar edip ardından ömrünün geri kalanını pişmanlık içinde bir manastırda geçirmesi', 'Köyüne dönüp dinsel bir tarikata katılması'], '1906\'da yazılan \'Ana\', sosyalist gerçekçiliğin örnek romanı sayılır; annenin politik bilinçlenmesi romanın asıl eksenidir.'),
  ('Gorki\'nin otobiyografik üçlemesinin doğru sıralaması hangisidir?', 'Çocukluğum, Ekmeğimi Kazanırken, Benim Üniversitelerim', ['Benim Üniversitelerim, Çocukluğum, Ekmeğimi Kazanırken', 'Çocukluğum, Benim Üniversitelerim, Ekmeğimi Kazanırken', 'Ekmeğimi Kazanırken, Çocukluğum, Benim Üniversitelerim'], 'Üçleme çocukluktan başlayıp çıraklık yıllarıyla sürer ve Kazan\'daki \'üniversitesi\' olan yaşam deneyimleriyle biter.'),
  ('Rus edebiyatında Nobel Edebiyat Ödülü\'nü ilk kazanan ve ödülü Fransa\'da göçmen olarak yaşarken alan yazar kimdir?', 'İvan Bunin', ['Lev Tolstoy', 'Maksim Gorki', 'Boris Pasternak'], 'Bunin 1933\'te ödülü Fransa\'da göçmen olarak yaşarken almıştır; Pasternak ödülü 1958\'de almış, Tolstoy ise hiç almamıştır.'),
  ('Bunin\'in \'San Francisco\'lu Bay\' öyküsünde adı bile verilmeyen zengin Amerikalının Capri\'de ani ölümü neyi vurgular?', 'Paranın ve gösterişin ölüm karşısındaki anlamsızlığını', ['Amerikan iş dünyasının yaşlı Avrupa\'ya karşı kesin üstünlüğünü', 'İtalyan otelcilerin konukseverliğini', 'Gemi yolculuklarının tehlikeli olduğunu'], 'Ölümünden sonra adamın cesedi bir soda kasasında, geminin karanlık ambarında geri gönderilir; öykü varlığın geçiciliğini ironik bir dille anlatır.'),
  ('Bir öğrenci \'Rus gerçekçiliğinde bastırılmış taşra kadınının trajedisi\' konulu bir sunum hazırlıyor ve iki örnek arıyor. Hangi çift bu konuya en uygundur?', 'Ostrovski\'nin \'Fırtına\'sı ve Leskov\'un \'Mtsensk İlçesinin Lady Macbeth\'i\'', ['Gogol\'ün \'Müfettiş\'i ve Çehov\'un \'Bukalemun\'u', 'Turgenyev\'in \'Babalar ve Oğullar\'ı ve Gonçarov\'un \'Oblomov\'u', 'Puşkin\'in \'Boris Godunov\' adlı tarihî dramı ve Lermontov\'un \'Borodino\' adlı şiiri'], 'İki eserin de kahramanı Katerina adlı, taşradaki tüccar evinde bunalan ve yıkıma sürüklenen bir kadındır; diğer çiftler erkek kahramanları ya da başka temaları öne çıkarır.'),
  ('Kendini \'son köy şairi\' olarak tanımlayan, dansçı Isadora Duncan ile evlenen ve 1925\'te otuz yaşında ölen Rus şair kimdir?', 'Sergey Yesenin', ['Velimir Hlebnikov', 'Nikolay Gumilyov', 'Andrey Bely'], 'Yesenin\'in şiirleri Rus köyünün yitip gidişini hüzünle işler; ölmeden önce kendi kanıyla bir veda şiiri yazmıştır.'),
  ('Sembolizmin belirsizliğine karşı açık, somut ve dengeli bir şiir dili isteyen ve Gumilyov, Ahmatova, Mandelştam\'ın temsil ettiği Rus şiir akımı hangisidir?', 'Akmeizm', ['İmajinizm', 'Fütürizm', 'Konstrüktivizm'], 'Akmeistler şiirde nesnelerin somut ağırlığını ve açıklığı savunmuşlardır; akımın adı Yunanca \'doruk\' anlamındaki akme sözcüğünden gelir.'),
  ('Usta ile Margarita\'da Woland\'ın Usta\'ya geri verdiği yakılmış romanla ilgili söylediği ünlü söz hangisidir?', 'Elyazmaları yanmaz.', ['Kelimeler uçar, yazı kalır.', 'Gerçek sanat ölümsüzdür.', 'Her kitap kendi okurunu bulur.'], 'Woland\'ın bu sözü, sansür ve baskıya karşın gerçek sanatın yok edilemeyeceği inancının simgesi olmuştur.'),
  ('Usta ile Margarita\'nın içindeki ikinci anlatı, yani Usta\'nın yazdığı roman kimin öyküsüdür?', 'Yahudiye valisi Pontius Pilatus\'un', ['Büyük Petro\'nun', 'Goethe\'nin de işlediği bilgin Faust\'un', 'Moskova Patriği\'nin'], 'Usta\'nın romanı, Pilatus\'un Yeşua\'yı (İsa) ölüme göndermesini ve vicdan azabını anlatır; bu bölümler Moskova\'daki olaylarla iç içe ilerler.'),
  ('Bulgakov\'un İç Savaş yıllarında Kiev\'deki Turbin ailesini anlattığı romanı hangisidir?', 'Beyaz Muhafız', ['Kara Kar', 'Ölümcül Yumurtalar', 'Bir Ölünün Notları'], '\'Beyaz Muhafız\'ın sahne uyarlaması \'Turbinlerin Günleri\', Stalin\'in pek çok kez izlediği bilinen bir oyun olmuştur.'),
  ('Ilf ve Petrov\'un \'On İki Sandalye\' romanında dolandırıcı Ostap Bender ve ortağının peşine düştüğü şey nedir?', 'Bir sandalyenin döşemesine saklanmış mücevherler', ['Çarın kaybolmuş tacı', 'Bir trende unutulmuş altın sandığı', 'Eski bir manastırın gizli hazine haritası'], 'Devrimden önce kayınvalidenin bir sandalyeye diktiği mücevherleri arayan kahramanlar, dağılmış takımın sandalyelerini Sovyetler Birliği boyunca kovalar.'),
  ('Şolohov\'un \'Bir İnsanın Yazgısı\' öyküsünde savaşta bütün ailesini yitiren Andrey Sokolov\'un yaşamına yeniden anlam katan şey nedir?', 'Savaş yetimi bir çocuğu evlat edinmesi', ['Kolhozda başkan seçilmesi', 'Esir kampından bir hazineyle dönmesi', 'Yeniden evlenip savaştan önce yaşadığı köyüne yerleşmesi'], 'Sokolov, kimsesiz küçük Vanya\'ya \'babası\' olduğunu söyler ve onu yanına alır; öykü savaş sonrası insanın onurunu ve dayanıklılığını işler.'),
  ('Durgun Don\'un ana karakteri olan ve Beyazlarla Kızıllar arasında savrulan Kazak kimdir?', 'Grigori Melehov', ['Pantelemon Prokofyeviç', 'Yuri Jivago', 'Pavel Korçagin'], 'Grigori Melehov, iki taraf arasında gidip gelen, sonunda her şeyini yitiren trajik bir kahramandır; Pavel Korçagin ise Ostrovski\'nin \'Ve Çeliğe Su Verildi\' romanının kahramanıdır.'),
  ('Soljenitsin\'in yaşamıyla ilgili hangisi doğrudur?', '1970\'te Nobel aldı, 1974\'te Sovyetler Birliği\'nden sınır dışı edildi', ['1958\'de Nobel aldı, ödülü reddetmek zorunda kaldı', 'Hiç kampta kalmadı, yaşamı boyunca Paris\'te yaşadı', 'Uzun yıllar Sovyet Yazarlar Birliği başkanlığı yaptı ve Moskova\'da öldü'], 'Soljenitsin 1970\'te Nobel\'i kazandı; \'Gulag Takımadaları\'nın yurt dışında yayımlanmasından sonra 1974\'te sınır dışı edildi ve 1994\'te Rusya\'ya döndü.'),
  ('Bir öğrenci Gümüş Çağ şairlerinin yaşam öykülerini inceliyor: biri 1921\'de kurşuna dizilmiş, eşi olan şair ise yıllarca baskı altında yaşamış, oğlu da kamplarda tutulmuştur. Söz konusu çift kimlerdir?', 'Nikolay Gumilyov ve Anna Ahmatova', ['Aleksandr Blok ve Zinaida Gippius', 'Vladimir Mayakovski ve Lilya Brik', 'Sergey Yesenin ve dansçı Isadora Duncan'], 'Gumilyov karşıdevrimci bir komploya katıldığı gerekçesiyle 1921\'de idam edilmiş; Ahmatova\'nın ve Gumilyov\'un oğlu Lev ise kamplarda yıllar geçirmiştir.'),
  ('\'Nerede geçen yılların karları?\' nakaratıyla tanınan baladın şairi olan, hırsızlık ve kavgalara karıştığı için idama mahkûm edilen 15. yüzyıl Fransız şairi kimdir?', 'François Villon', ['Charles d\'Orléans', 'Clément Marot', 'Pierre de Ronsard'], 'Villon\'un \'Vasiyetname\'sindeki \'Geçmiş Zaman Kadınları Baladı\' ve \'Asılmışlar Baladı\' ölüm ve geçicilik temasını içtenlikle işler.'),
  ('Rabelais\'nin Gargantua\'da tasarladığı Thélème Manastırı\'nın tek kuralı nedir?', 'Ne istersen onu yap.', ['Çalış ve dua et.', 'Sessizlik altındır.', 'Tanrı\'dan kork, krala hizmet et.'], 'Thélème, Orta Çağ manastır düzeninin tersine, özgür ve iyi yetiştirilmiş insanların kendi iradeleriyle yaşadığı hümanist bir ütopyadır.'),
  ('Montaigne\'in hem kuşkuculuğunu hem de kendini sorgulama tavrını özetleyen ünlü sözü hangisidir?', 'Ne biliyorum ki?', ['Düşünüyorum, öyleyse varım.', 'Bildiğim tek şey hiçbir şey bilmediğimdir.', 'İnsan her şeyin ölçüsüdür.'], 'Montaigne bu soruyu bir madalyada parola olarak kullanmıştır; \'Düşünüyorum, öyleyse varım\' Descartes\'ın, öbürleri antik düşünürlerin sözleridir.'),
  ('16. yüzyılda Ronsard ve Du Bellay\'in önderliğinde Fransızcayı antik dillerle yarışacak bir şiir diline dönüştürmeyi amaçlayan şair grubu hangi adla anılır?', 'Pléiade', ['Parnas', 'Félibrige', 'Cénacle'], 'Pléiade\'ın bildirisi sayılan \'Fransız Dilinin Savunması ve Yüceltilmesi\' 1549\'da Du Bellay tarafından yayımlanmıştır.'),
  ('Ronsard\'ın \'Çok yaşlandığınızda, akşam mum ışığında...\' diye başlayan Hélène\'e sonesinde sevgiliye verilen öğüt hangi temaya bağlıdır?', 'Anı yaşa; gençlik ve güzellik geçmeden yaşamın tadını çıkar', ['Dünya malına değer verme, öteki dünyayı düşün', 'Ulusuna ve kralına bağlı kal', 'Aşkı gizle, toplumun ayıplamasından kork'], 'Ronsard, yaşlandığında güzelliğini ona övgü yazan şairi hatırlayacağını söyleyip sevgiliye \'bugünden yaşamın güllerini topla\' der; bu, carpe diem temasıdır.'),
  ('Fransız Akademisi\'nin (Académie française) kuruluşuyla ilgili hangisi doğrudur?', '1635\'te Kardinal Richelieu\'nün desteğiyle kurulmuştur', ['1789\'da Fransız Devrimi\'nin ardından halk meclisi tarafından kurulmuştur', 'Napolyon\'un emriyle 1804\'te kurulmuştur', 'Rönesans\'ta I. François\'nın sarayında 1530\'da kurulmuştur'], 'Richelieu\'nün himayesinde 1635\'te kurulan Akademi, Fransız dilini düzenlemek ve bir sözlük hazırlamakla görevlendirilmiştir.'),
  ('Fransız klasik tragedyasında \'bienséance\' (uygunluk) ilkesi gereği sahnede genellikle gösterilmeyen şey hangisidir?', 'Ölüm ve şiddet sahneleri', ['Kral ve kraliçelerin konuşmaları', 'Kahramanın iç çatışmasını anlatan tiradlar', 'Sırdaşlarla yapılan konuşmalar'], 'Klasik kurallara göre seyirciyi rahatsız edecek kanlı olaylar sahnede gösterilmez, bir haberci ya da sırdaş aracılığıyla anlatılır.'),
  ('Bir tiyatro öğrencisi, Racine\'in Phèdre\'ini ve Corneille\'in tragedyalarını sahnelerken oyuncuların on iki heceli uzun dizelerle konuştuğunu fark ediyor. Fransız klasik tragedyasının bu temel ölçüsüne ne ad verilir?', 'Aleksandren', ['Hendekasilab', 'Pentametre', 'Heksametre'], 'Aleksandren on iki heceli, genellikle ortasından duraklı Fransız dizesidir; klasik tragedya ve komedyaların büyük bölümü bu ölçüyle yazılmıştır.'),
  ('Molière\'in \'İnsan Düşmanı\' (Le Misanthrope) komedisinde Alceste\'in toplumdan nefret etmesine karşın âşık olduğu kadının karakteri nasıldır?', 'Koket, dedikoduya yatkın ve herkese hoş görünen Célimène', ['Dindar, ağırbaşlı ve toplumda saygın bir akıl hocası olan Éliante', 'Saf ve evcimen Agnès', 'Hizmetçi Dorine'], 'Alceste dürüstlüğü uğruna toplumdan kopmak isterken, uyumlu ve flörtöz Célimène\'e tutkuyla bağlıdır; bu çelişki oyunun kaynağıdır.'),
  ('Molière\'in \'Kadınlar Okulu\' komedisinde Arnolphe, evleneceği genç kızı nasıl yetiştirmiştir?', 'Hiçbir şey öğrenmesin ve kendisini aldatamasın diye cahil bırakarak', ['Soylu bir hanımefendi olsun diye saray terbiyesiyle', 'Rahibeler arasında dinî eğitimle', 'Yurt dışına göndererek'], 'Arnolphe aldatılmaktan korktuğu için Agnès\'i bilerek cahil yetiştirir; ama genç kız aşkı kendiliğinden öğrenir ve plan çöker.'),
  ('Molière\'in \'Don Juan\' oyununda başkarakterin sonu nasıl gelir?', 'Bir heykelin davetine uyup yer yarılarak cehenneme çekilir', ['Düelloda öldürülür', 'Manastıra kapanır', 'Sevdiği kadınla evlenip pişman olur'], 'Don Juan, öldürdüğü Komutan\'ın heykelini yemeğe çağırır; heykel gelince alevler içinde yerin dibine gömülür. Uşağı Sganarelle ise ücretini kaybettiğine yanar.'),
  ('Molière\'in 1659\'da sahnelenen ve salonlarda abartılı inceliği moda edinen kadınları alaya alan komedisi hangisidir?', 'Gülünç Kibarlar (Les Précieuses ridicules)', ['Scapin\'in Dolapları (Les Fourberies de Scapin)', 'Zoraki Doktor (Le Médecin malgré lui)', 'Cimri (L\'Avare) komedisi'], 'Bu tek perdelik komedi, salon kültüründeki yapmacık incelik ve aşırı süslü dili hicveder; Molière\'in Paris\'te ilk büyük başarısıdır.'),
  ('Molière\'in kurduğu topluluğun mirasının, 1680\'de devlet eliyle kurulan hangi kuruma aktığı söylenir?', 'Comédie-Française', ['Opéra-Comique', 'Odéon', 'Théâtre du Châtelet'], 'Molière\'in ölümünden sonra topluluğu başka bir kadro ile birleşti ve 1680\'de Comédie-Française doğdu; kurum bugün de \'Molière\'in Evi\' diye anılır.'),
  ('Molière\'in karakter komedilerinde komiklik neden doğar?', 'Bir tutkunun ya da saplantının kişiyi uç noktaya sürüklemesinden', ['Rastlantıların art arda gelmesinden ve kişilerin sürekli birbirini yanlış tanımasından', 'Kişilerin yabancı dil konuşmasından', 'Kralın taklit edilmesinden'], 'Cimri\'de para, Hastalık Hastası\'nda hastalık takıntısı gibi tek bir ruh hâli abartıldıkça güldürü ve toplumsal eleştiri birlikte ortaya çıkar.'),
  ('Pascal\'ın insanı \'düşünen saz\' (roseau pensant) diye nitelemesinde vurgulanan temel düşünce hangisidir?', 'İnsan doğada çok zayıftır ama düşünebildiği için evrenden üstündür', ['İnsan doğanın efendisi olduğu için hiçbir güçten etkilenmediğini ve her şeye hâkim olduğunu', 'İnsan yalnızca duygularıyla yaşar', 'İnsan sazın sesine boyun eğer'], 'Pascal\'a göre evren insanı ezebilir, ancak insan bunu bildiği için, yani düşündüğü için onurludur.'),
  ('La Rochefoucauld\'nun \'Düşünceler ve Özdeyişler\'inde (Maximes) insan davranışlarını açıklarken öne çıkardığı temel güdü nedir?', 'Kendini sevme (amour-propre) ve çıkar', ['Merhamet ve karşılıksız yardımseverlik', 'Akıl yürütmenin üstünlüğü ve bilgi', 'Vatan sevgisi ve fedakârlık'], 'Kısa, keskin özdeyişlerde erdemlerin bile çoğu zaman gizli bir çıkara ya da kibre dayandığı ileri sürülür; bu bakış karamsar ahlakçılığın klasiğidir.'),
  ('La Bruyère\'in \'Karakterler\' adlı kitabı hangi edebî ürünün Fransız ahlakçılığındaki örneği sayılır?', 'Çağdaş toplumun tiplerini ve huylarını kısa portrelerle çizen betimleme', ['Karşılıklı aşk mektuplarından oluşan, hayalî kişiler arasında geçen uzun bir roman', 'Şövalye destanı', 'Manzum bir tragedya'], 'La Bruyère, Theophrastos\'tan çevirdiği karakter yazılarına kendi çağının saray ve kent tiplerini ekleyerek kısa portreler halinde sunmuştur.'),
  ('Voltaire\'in \'Zadig\' ve \'Micromégas\' gibi kısa anlatıları hangi türün örnekleridir?', 'Felsefi öykü (conte philosophique)', ['Şövalye romansı (roman de chevalerie)', 'Pastoral şiir (poésie pastorale)', 'Tarihî dram (drame historique)'], 'Voltaire, hayalî doğu ya da evren yolculuğu çerçevesinde akıl, hoşgörü ve kötülük sorunu gibi felsefi fikirleri öykü diliyle işlemiştir.'),
  ('Voltaire\'in Kalas olayı üzerine yazdığı \'Hoşgörü Üzerine İnceleme\'sinde savunduğu temel ilke nedir?', 'Dinî fanatizme karşı hoşgörü ve düşünce özgürlüğü', ['Tek mezhebin zorla herkese kabul ettirilmesi', 'Din adamlarına siyasi yetki verilmesi ve yargı bağışıklığı', 'Köleliğin yasayla düzenlenerek sürdürülmesi'], 'Protestan tüccar Jean Calas\'ın haksız yere idam edilmesi üzerine Voltaire, fanatizmi eleştirip yargı adaleti ve hoşgörü çağrısı yapmıştır.'),
  ('Rousseau\'nun \'İtiraflar\' adlı yapıtının edebiyat tarihindeki yeri nedir?', 'Modern otobiyografinin öncü örneklerinden biri sayılması', ['Fransa\'nın ilk tarih romanı olarak yazılması ve Napolyon\'un yaşamını anlatması', 'İlk polisiye roman olması', 'Manzum bir destan olması'], 'Rousseau, kendi kusurlarını da açıkça yazdığı bu eserle, kişinin iç dünyasını bütünüyle anlatan modern otobiyografik yazının yolunu açmıştır.'),
  ('Rousseau\'nun \'İnsanlar Arasındaki Eşitsizliğin Kaynağı\' adlı söyleminde eşitsizliğin doğuşu nasıl açıklanır?', 'Özel mülkiyetin ortaya çıkışıyla', ['Tanrısal bir yazgıyla ve soylulukla', 'Akıl yürütme yeteneğinin yokluğuyla', 'Doğuştan gelen soyluluk ve kan bağıyla'], 'Rousseau, ilk kez bir toprağı çevirip \'bu benimdir\' diyenin uygarlığın ve eşitsizliğin kurucusu olduğunu söyler.'),
  ('Rousseau\'nun \'Yeni Héloïse\' romanının biçimsel özelliği nedir?', 'Kahramanlar arasındaki mektuplardan oluşan bir mektup romanı olması', ['Tek bir günlükten oluşması', 'Manzum yazılması', 'Tiyatro metni olarak kurulması'], 'Julie ile Saint-Preux\'ün aşkını mektuplarla anlatan roman, duygusallığı ve doğa betimleriyle romantizmi hazırlayan önemli yapıtlardan biridir.'),
  ('Montesquieu\'nün \'Kanunların Ruhu\' adlı eserinin siyaset düşüncesine katkısı hangisidir?', 'Yasama, yürütme ve yargı erklerinin ayrılması ilkesini işlemesi', ['Mutlak monarşiyi savunması', 'Mülkiyetin kaldırılmasını önermesi', 'Seçimlerin yasaklanmasını istemesi'], 'Montesquieu, özgürlüğün korunması için erklerin birbirini sınırlaması gerektiğini söyler; bu fikir modern anayasalara girmiştir.'),
  ('Beaumarchais\'nin \'Figaro\'nun Evliliği\' komedisinin 1784\'te sahnelenmesinde dikkat çeken toplumsal yön nedir?', 'Uşak Figaro\'nun soylu kontla zekâ düzeyinde başa baş mücadele ederek ayrıcalıkları eleştirmesi', ['Kralın başrolde olması', 'Soyluların yoksulları koruması', 'Köylülerin şölenle sevinmesi'], 'Figaro, efendisi Kont Almaviva\'yı zekâsıyla alt eder; oyun sınıf ayrıcalıklarını eleştirmesi nedeniyle devrim öncesi tartışmalara yol açmıştır.'),
  ('Beaumarchais\'nin Figaro oyunlarına dayanan hangi iki ünlü opera vardır?', 'Rossini\'nin Sevil Berberi\'si ve Mozart\'ın Figaro\'nun Düğünü', ['Verdi\'nin Aida\'sı ve Puccini\'nin Tosca\'sı', 'Bizet\'nin Carmen\'i ve Wagner\'in Tannhäuser\'i', 'Donizetti\'nin Lucia\'sı ve Mozart\'ın Don Giovanni\'si'], '\'Sevil Berberi\' Rossini\'ye, \'Figaro\'nun Evliliği\' ise Mozart\'a kaynaklık etmiştir.'),
  ('Abbé Prévost\'nun \'Manon Lescaut\' romanında kahraman des Grieux\'nün trajedisinin kaynağı nedir?', 'Lüks düşkünü Manon\'a olan karşı konulmaz tutkusu', ['Ruhban sınıfına kabul edilmemesi ve kovulması', 'Savaşta yenilip esir düşmesi', 'Ailesinin mirasını yitirip yoksullaşması'], 'Genç şövalye des Grieux, Manon\'un uğruna her şeyi göze alır; roman tutku ile ahlak ve toplum arasındaki çatışmanın klasiği olarak kabul edilir.'),
  ('Sefiller\'de Javert\'in sonu nasıl olur?', 'Valjean\'ı bırakmanın yarattığı vicdan çatışması yüzünden Seine Nehri\'ne atlar', ['Barikatta vurularak ölür', 'Valjean tarafından öldürülür', 'Hapse düşer ve orada ölür'], 'Yasaya mutlak bağlı Javert, kendisini bağışlayan Valjean\'ı tutuklayamaz; değer dünyası çökünce kendini Seine\'e bırakır.'),
  ('Sefiller\'de yaralı Marius\'u kurtarmak için Jean Valjean\'ın geçtiği yer neresidir?', 'Paris\'in lağım kanalları', ['Seine Nehri\'nin altından geçen bir tünel', 'Notre-Dame Katedrali\'nin çatı katı', 'Terk edilmiş bir kömür madeni galerisi'], 'Valjean, baygın Marius\'u sırtlayıp lağım kanallarından geçirir; Hugo bu bölümde Paris lağımlarını da uzun uzun betimler.'),
  ('Victor Hugo, III. Napolyon\'un darbesi sonrası uzun yıllar hangi adalarda sürgün yaşamıştır?', 'Jersey ve Guernsey', ['Korsika ve Elba', 'Sicilya ve Sardinya', 'Korfu ve Girit'], 'Hugo, 1851 darbesinden sonra Belçika\'ya, ardından Manş Adaları\'ndaki Jersey ve Guernsey\'e gitti; Sefiller\'i sürgündeyken tamamladı.'),
  ('Alexandre Dumas\'nın \'Monte Cristo Kontu\'nda Edmond Dantès, Château d\'If hapishanesinde kimden öğrenim görür ve hazine haritasını alır?', 'Abbé Faria\'dan', ['Fernand Mondego\'dan, eski rakibinden', 'Villefort\'tan, savcı yardımcısından', 'Caderousse\'tan, komşu terziden'], 'Dantès, yan hücredeki bilgili rahip Faria\'dan hem eğitim görür hem de Monte Cristo adasındaki hazinenin yerini öğrenir.'),
  ('Mérimée\'nin \'Colomba\' novellasında öne çıkan toplumsal tema nedir?', 'Korsika\'da kan davası (vendetta) geleneği', ['Sanayi devriminin kırsala etkileri', 'Fransız Devrimi\'nin kurbanlarının intikamı', 'Haçlı seferlerinin Korsika\'ya yansıması'], 'Genç Colomba, ağabeyini babalarının intikamını almaya zorlar; Mérimée Korsika\'nın yerel geleneklerini sert bir gerçekçilikle yansıtır.'),
  ('George Sand takma adını kullanan yazarın gerçek adı nedir?', 'Aurore Dupin', ['Marie d\'Agoult', 'Germaine de Staël', 'Louise Colet'], 'Aurore Dupin, Baronne Dudevant olarak evlendi; yazarlığa erkek takma adıyla başladı, giysi ve yaşam biçimiyle de dönemin kuralları dışına çıktı.'),
  ('Alfred de Musset\'nin \'Bir Çağ Çocuğunun İtirafı\' adlı yapıtı hangi duyguyu en çok yansıtır?', 'Napolyon sonrası kuşağın yaşadığı hayal kırıklığı ve umutsuzluğu', ['Devrimin coşkusunu', 'Taşra yaşamının sevincini', 'Din savaşlarının dehşetini'], 'Romantizmin \'çağ hastalığı\' denilen mal du siècle\'i, Musset\'nin bu otobiyografik romanında George Sand\'la yaşadığı ilişkiyle birlikte işlenir.'),
  ('Alfred de Vigny\'nin \'Chatterton\' adlı oyununun teması nedir?', 'Toplumun anlamadığı şairin yalnızlığı ve intiharı', ['Savaş kahramanının zaferle yurduna dönüşü', 'Krallar arasındaki saray entrikaları', 'Kentsoyluların evlilik pazarlıkları'], 'Vigny, genç İngiliz şair Chatterton\'ı örnek alarak parayı öne çıkaran bir toplumda şairin yalnızlığını ve yıkımını anlatır.'),
  ('Stendhal\'in \'Parma Manastırı\' romanında Fabrice del Dongo, kendini hangi tarihî savaşın içinde bulur?', 'Waterloo Savaşı', ['Austerlitz Savaşı', 'Borodino Savaşı', 'Sedan Savaşı'], 'Fabrice, Napolyon hayranlığıyla savaşa katılır ama Waterloo\'da ne olup bittiğini bile anlayamaz; sahne savaş betimlerinin bir klasiğidir.'),
  ('Stendhal\'in gerçek adı nedir?', 'Henri Beyle', ['Honoré Balsac', 'Marie-Henri Dupin', 'Louis Beyle-Dumas'], 'Henri Beyle, Alman kentindeki Stendal\'dan esinlenerek Stendhal takma adını kullanmış, eserlerinde birçok başka mahlas da denemiştir.'),
  ('Kırmızı ve Siyah\'ta Julien Sorel\'in sonu nasıl olur?', 'Madame de Rênal\'a ateş ettiği için yargılanıp idam edilir', ['Mathilde ile evlenip soylu olur', 'Askerliğe döner ve generalliğe yükselir', 'Manastıra çekilip ölür'], 'Julien, bir mektup yüzünden hırsla Madame de Rênal\'ı vurur; savunma yapmayı reddedip giyotinle idam edilir.'),
  ('Balzac\'ın \'Goriot Baba\' romanında Rastignac\'ın Paris\'e bakıp söylediği \'Şimdi sıra bizde!\' meydan okuması ne anlama gelir?', 'Toplumda yükselmek için kenti fethetme kararı', ['Orduya katılıp savaşa gitme kararı', 'Paris\'ten sürgüne çekilip yazarlığa başlama', 'Kız kardeşinden ayrılıp taşraya dönme'], 'Genç Rastignac, Goriot\'nun mezarından sonra Paris\'e bakıp toplumsal yükselme mücadelesine girmeye karar verir.'),
  ('Madame Bovary 1857\'de yayımlanınca Flaubert hakkında açılan davanın nedeni neydir?', 'Kamu ahlakına ve dine aykırılık suçlaması', ['Başka bir yazardan intihal yaptığı iddiası', 'Devlet sırrını açıklamış olma suçlaması', 'Devlet başkanına hakaret suçlaması'], 'Roman önce bir dergide tefrika edildi, ardından savcılık ahlaka aykırı olduğu iddiasıyla Flaubert\'i yargıladı; yazar beraat etti.'),
  ('Madame Bovary\'de Yonville eczacısı Homais\'nin temsil ettiği tip hangisidir?', 'Bilimci görünümlü, kendini beğenmiş ve sığ burjuva', ['Fedakâr, halk için çalışan bir köy doktoru', 'İdealist ve toplumcu bir devrimci genç', 'Saf, duygusal ve romantik bir âşık'], 'Homais, \'ilerleme\' sözleriyle kendini önemseyen ama çıkarcı ve kültürsüz taşra burjuvasıdır; Flaubert\'in ironisinin başlıca hedeflerinden biridir.'),
  ('Flaubert\'in Kartaca\'daki paralı askerlerin isyanını anlattığı tarihî romanı hangisidir?', 'Salammbô', ['Hérodias', 'Aziz Antonius\'un Ayartılması', 'Bouvard ve Pécuchet'], 'Salammbô, Kartaca\'nın eski çağındaki paralı askerler ayaklanmasını egzotik ve yoğun betimlemelerle anlatan romandır.'),
  ('Zola\'nın \'Nana\' romanında başkarakterin sonu nasıl anlatılır?', 'Çiçek hastalığından yüzü bozularak ölür', ['Suçlanıp mahkemece idam edilir', 'Evlenip köyde sakin bir yaşam sürer', 'Savaşta cephede vurularak ölür'], 'Paris\'in erkeklerini yoksulluğa sürükleyen Nana, hastalıktan çürüyerek ölür; Zola burada toplumun çürümüşlüğünü simgeler.'),
  ('Zola\'nın \'Hayvan İnsan\' (La Bête humaine) romanında hangi araç ve alan öne çıkar?', 'Demiryolu ve lokomotif', ['Gemi ve liman çevresindeki işçi yaşamı', 'Kömür madeni ve yeraltı işçileri', 'Büyük mağaza ve tezgâhtar kadınlar'], 'Roman, lokomotif makinisti Jacques Lantier\'in kalıtsal şiddet eğilimini demiryolu çevresinde işler.'),
  ('Maupassant\'ın \'Bel-Ami\' romanında Georges Duroy\'un yükselişi nasıl gerçekleşir?', 'Kadınların desteğiyle ve ahlaki kaygı gütmeden gazetecilikte yükselerek', ['Askerî rütbeyle', 'Bilimsel icatlarla', 'Ailesinden gelen mirasla'], 'Eski asker Duroy, çevresindeki kadınları kullanarak gazetede ve toplumda yükselir; roman cinsel ve siyasi çıkarcılığı sergiler.'),
  ('Maupassant\'ın \'Horla\' adlı fantastik öyküsünde anlatıcının yaşadığı durum nedir?', 'Görünmez bir varlığın kendisini ele geçirdiğine inanıp delirmeye sürüklenmesi', ['Gizli bir hazineyi bulması', 'Zamanda yolculuk yapması', 'Bir cinayeti çözmesi'], 'Günlük biçiminde yazılan öykü, anlatıcının artan paranoyasını verir; Maupassant\'ın kendi ruhsal çöküşünü yansıttığı söylenir.'),
  ('Alphonse Daudet\'nin \'Son Ders\' öyküsünde sınıfta öğretmenin yaptığı son konuşmanın temel duygusu nedir?', 'Dil ve vatan kaybının hüznü', ['Savaş zaferinin yarattığı coşku', 'İşsizlik ve gelecek kaygısı', 'Okul reformunun getirdiği sevinç'], 'Alsace\'ın Prusya\'ya bırakılması üzerine öğretmen Hamel, öğrencilerine Fransızca verdiği son dersi hüzünle anlatır.'),
  ('Goncourt kardeşler (Edmond ve Jules) adına verilen ödül hangi alanda ve ne zamandan beri verilir?', 'Roman alanında, 1903\'ten beri', ['Şiir alanında, 1850\'den beri', 'Tiyatro alanında, 1920\'den beri', 'Bilim kitapları alanında, 1930\'dan beri'], 'Edmond de Goncourt\'un vasiyetiyle kurulan Académie Goncourt, 1903\'ten beri yıllık roman ödülü verir.'),
  ('Aşağıdaki yazarlardan hangisi natüralist okulun Médan çevresiyle ilişkilendirilmez?', 'Victor Hugo', ['Émile Zola', 'Guy de Maupassant', 'Joris-Karl Huysmans'], 'Hugo, Zola\'dan önceki kuşağın romantik yazarıdır. Maupassant ve Huysmans ise Médan Akşamları\'nda öykü yayımlamış natüralist çevrede yer almıştır.'),
  ('Flaubert\'in yapıtlarında en çok dikkat edilen biçimsel kaygı hangisidir?', 'Üslupta mükemmellik, cümlenin ritmi ve uyumu', ['Çok sayıda ve uzun diyalog kurma', 'Aforizmalarla ders verme eğilimi', 'Yöresel ağızları olduğu gibi taklit etme'], 'Flaubert, cümleyi defalarca yeniden yazar ve sesli okuyarak ritmini denetlerdi; üslup konusundaki titizliği ünlüdür.'),
  ('Natüralizm ile gerçekçilik arasındaki başlıca fark hangisidir?', 'Natüralizm, kalıtım ve çevre gibi bilimsel nedenselliği ön plana çıkarır', ['Gerçekçilik şiire bağlıdır, natüralizm tiyatroya', 'Gerçekçilik hayal ürünüdür, natüralizm değil', 'Natüralizm yalnızca tarihî olayları anlatır'], 'Natüralist yazar insanı kalıtım, çevre ve dönemin etkileriyle açıklar; gerçekçilik ise daha geniş bir gözlem ve toplum betimlemesine dayanır.'),
  ('Parnas şiir okulunun şiirde savunduğu temel ilke hangisidir?', 'Duygusal taşkınlık yerine biçim mükemmelliği ve nesnellik', ['Kişisel itirafların serbestçe dökülmesi', 'Halk deyişlerinin doğrudan aktarılması', 'Siyasi propagandanın öncelenmesi'], 'Parnasyenler, romantiklerin duygusal taşkınlığına karşı soğukkanlı, ölçülü ve kusursuz biçimli şiiri savunmuşlardır.'),
  ('Baudelaire\'in \'Albatros\' şiirinde albatros neyin simgesidir?', 'Göklerde görkemli, yerde beceriksiz kalan şairin toplumdaki yabancılığının', ['Savaşın', 'Aşkın kutsallığının', 'Yolculuğun sevincinin'], 'Gökte güçlü uçan ama güverteye indiğinde alay edilen kuş, şairin toplum içindeki yersiz ve acı durumunu simgeler.'),
  ('Baudelaire\'in Fransızcaya çevirerek tanıttığı Amerikalı yazar kimdir?', 'Edgar Allan Poe', ['Walt Whitman', 'Nathaniel Hawthorne', 'Herman Melville'], 'Baudelaire, Poe\'nun öykülerini ve şiirlerini yıllarca çevirdi; Poe Fransız sembolizmini etkiledi.'),
  ('Mallarmé\'nin \'Bir Faun\'un Öğleden Sonrası\' şiirinden esinlenerek hangi besteci ünlü bir orkestra parçası yazmıştır?', 'Claude Debussy', ['Maurice Ravel, \'Bolero\' bestecisi', 'Erik Satie, \'Gymnopédie\' bestecisi', 'Gabriel Fauré, \'Requiem\' bestecisi'], 'Debussy\'nin 1894 tarihli \'Bir Faun\'un Öğleden Sonrası\'na Prelüd\', müzikte izlenimciliğin simge yapıtlarındandır.'),
  ('Rimbaud\'nun \'Cehennemde Bir Mevsim\' kitabı hangi tür yazım örneğidir?', 'Düzyazı ve şiirden oluşan otobiyografik, bunalımlı bir metin', ['Klasik tragedya', 'Mektup romanı', 'Seyahat günlüğü'], '1873\'te yayımlanan eser, Rimbaud\'nun şiir, aşk ve hayata dair iç hesaplaşmasını sert bir dille anlatır.'),
  ('Cyrano de Bergerac\'ın sonunda Roxane gerçeği ne zaman öğrenir?', 'Cyrano ölürken, mektupları kimin yazdığını anlayınca', ['Düğün gecesi', 'Cyrano\'nun cenazesinde', 'Hiçbir zaman öğrenmez'], 'Yıllarca manastırda yaşayan Roxane, Cyrano\'nun ölüm anında mektubu okurken sesinden gerçeği anlar.'),
  ('Cyrano\'nun ölürken \'tek bir şeyi, kirletmeden götürüyorum\' dediği şey nedir?', 'Beyaz tüyü', ['Kılıcını, onurunun simgesi olarak', 'Şiirlerini, miras olarak', 'Burnunu, çirkinliğinin simgesi olarak'], 'Panache, onurlu ve gösterişli cesareti simgeler; Cyrano ölümüne bile bu soylu tavrı koruyarak gider.'),
  ('Gide\'in \'Dar Kapı\' romanında Alissa\'nın yaşamını belirleyen güç nedir?', 'Katı dinî ahlakın yüceltilmesi ve dünyevi mutluluktan vazgeçme', ['Hırs ve para', 'Savaş', 'Soylu olma isteği'], 'Alissa, Jérôme\'a duyduğu sevgiyi ahlaki çile uğruna reddeder ve kendini yok eder.'),
  ('Proust\'un \'Kayıp Zamanın İzinde\' dizisi kaç ciltten oluşur?', 'Yedi', ['Dört', 'On iki', 'Üç'], 'Dizi, \'Swann\'ların Tarafı\' ile başlar ve \'Zaman Yeniden Bulundu\' ile sona erer.'),
  ('Proust, dizinin büyük bölümünü hangi koşullarda yazmıştır?', 'Astımla boğuşarak, yatağında ve mantar kaplı odasında', ['Cezaevinde', 'Savaş cephesinde', 'Gemide yolculuk ederken'], 'Proust\'un hastalığı nedeniyle ses ve toza karşı koruyan mantar kaplı odası ünlüdür.'),
  ('Céline\'in \'Gecenin Sonuna Yolculuk\' romanı hangi duyguyu öne çıkarır?', 'Savaşın ve toplumun anlamsızlığına duyulan karamsarlık ve öfke', ['Aşkın coşkusu', 'Dinî huzur', 'Vatan sevgisi'], 'Anlatıcı Bardamu, cephe, sömürge ve fabrikada insanlığın saçmalığını argo ve konuşma dilinin gücüyle anlatır.'),
  ('Camus\'nün \'Yabancı\' romanında Meursault\'nun mahkemede ağır cezaya çarptırılmasında hangi unsur belirleyici olur?', 'Annesinin cenazesinde gözyaşı dökmemesi ve toplumun beklentilerine uymaması', ['Bir ülke sırrını sızdırmış olması', 'Sahte para basması', 'Kaçakçılık yapması'], 'Meursault\'nun duygusuz görünen tavrı, mahkemece suç kadar önemsenir; roman toplumun bireyden beklediği rollere yönelik bir eleştiridir.'),
  ('Meursault\'nun Yabancı\'da Arap\'ı öldürmesinin nedeni anlatıda nasıl açıklanır?', 'Güneşin ve sıcağın bunaltmasıyla, bilinçli bir kin olmadan', ['Eski bir kan davası', 'Soygun girişimi', 'Bir kıskançlık krizi'], 'Meursault duruşmada, sıcağın ve güneşin ışığı yüzünden tetiği çektiğini söyler; bu, olayın absürt niteliğini vurgular.'),
  ('Camus\'nün düşüncesinde \'absürt\' neyi anlatır?', 'İnsanın anlam arayışı ile evrenin sessizliği arasındaki uyumsuzluğu', ['Dinî inancın kesinliğini', 'Bilimin sınırsızlığını', 'Siyasi iktidarın doğruluğunu'], 'Camus\'ya göre insan anlam ister, dünya ise buna yanıt vermez; absürt bu çatışmadan doğar.'),
  ('Camus 1957\'de Nobel Edebiyat Ödülü\'nü aldığında hangi niteliğiyle öne çıkar?', 'Ödülü alan en genç yazarlardan biri olması', ['Ödülü reddeden ilk yazar olması', 'Aynı yıl iki farklı ödül birden alması', 'Ödülün parasını okula bağışlama sözü vermesi'], 'Camus 44 yaşında Nobel almıştır; ödül konuşmasında yazarın hakikate ve özgürlüğe hizmet etme sorumluluğundan söz etmiştir.'),
  ('Sartre\'ın kurduğu \'Les Temps Modernes\' dergisi hangi görüşün yayın organıdır?', 'Varoluşçu ve toplumsal angajmanı savunan düşüncenin', ['Sembolizmin', 'Dada akımının', 'Natüralizmin'], '1945\'te Sartre, Beauvoir ve Merleau-Ponty\'nin kurduğu dergi, yazarın toplumsal sorumluluğunu savunan sol aydın çevresinin sesiydi.'),
  ('Sartre\'ın \'Edebiyat Nedir?\' kitabında savunduğu \'angajman\' anlayışı neyi gerektirir?', 'Yazarın içinde yaşadığı toplumsal ve siyasi sorunlara karşı sorumluluk alması', ['Yalnızca güzel biçim peşinde olması', 'Eserlerini siyasetten tamamen uzak tutması', 'Kralın koruması altında yazması'], 'Sartre\'a göre yazmak bir eylemdir; yazar sessiz kalsa bile bir tavır almış olur.'),
  ('Sartre\'ın \'Sözcükler\' adlı yapıtı hangi türdedir?', 'Çocukluğunu anlattığı otobiyografi', ['Fransız Devrimi\'ni anlatan tarihî roman', 'Manzum bir trajedi oyunu', 'Afrika yolculuğunu anlatan gezi yazısı'], '\'Les Mots\', Sartre\'ın kitaplar arasında geçen çocukluğunu ironik bir dille anlatır.'),
  ('Ionesco\'nun \'Sandalyeler\' oyununda yaşlı çiftin gün boyu yaptığı şey nedir?', 'Görünmeyen konukları karşılayıp onlara sandalye yetiştirmek', ['Evi boyamak', 'Mektup yazmak', 'Pazara gitmek'], 'Sahne giderek boş sandalyelerle dolar; oyun iletişimsizlik ve yaşam boşluğu temalarını absürt biçimde yansıtır.'),
  ('Ionesco\'nun \'Ders\' (La Leçon) oyununda profesörün öğrencisine yaptığı son hareket nedir?', 'Dersin sonunda öğrencisini öldürmesi', ['Öğrencisine diploma vermesi ve uğurlaması', 'Öğrencisine evlilik teklif etmesi', 'Öğrencisini kapı dışarı edip kovması'], 'Dil dersi, giderek öğretmenin öğrenciye karşı şiddet ve baskısına dönüşür; oyun otoritenin dille uyguladığı iktidarı yansıtır.'),
  ('Beckett, 1969 Nobel Edebiyat Ödülü\'nü hangi niteliğiyle bilinen bir yazar olarak almıştır?', 'İrlanda doğumlu olup yapıtlarının önemli bölümünü Fransızca yazan', ['Fransa doğumlu ve İngilizce yazan', 'Almanya doğumlu ve İtalyanca yazan', 'İtalya doğumlu ve İspanyolca yazan'], 'Beckett İrlanda\'da doğdu ve Paris\'te yaşadı; \'Godot\'yu Beklerken\' gibi yapıtlarını önce Fransızca yazdı.'),
  ('Queneau\'nun \'Zazie Metroda\' romanının dilsel özelliği nedir?', 'Konuşma dilinin sesini yansıtan yazım ve oyunlu dil kullanımı', ['Latince cümleler', 'Eski Fransızca', 'Tek heceli sözcükler'], 'Queneau, Paris\'in konuşma diline yakın yazım ve sözcük oyunlarıyla alışılmış edebî dili çarpıtır.'),
  ('Oulipo grubunun temel ilkesi nedir?', 'Yazına bilinçli olarak kısıtlamalar ve matematiksel kurallar getirmek', ['Tam serbest yazı', 'Bilinçdışının otomatik yazısı', 'Halk türkülerinin toplanması'], '1960\'ta Queneau ve Le Lionnais\'nin kurduğu grup, yaratıcılığı kurallı sınırlamalarla geliştirmeyi amaçlar.'),
  ('Eski İngiliz şiirinde \'balina yolu\' (hronrad) gibi, iki sözcükle başka bir şeyi dolaylı anlatan söz sanatına ne ad verilir?', 'Kenning', ['Metafor yığınları', 'Ağıt', 'Karşılaştırma (simile) dizisi'], 'Kenning, \'deniz\' yerine \'balina yolu\' demek gibi bileşik bir tamlamayla bir varlığı ima etme tekniğidir; Eski İngiliz ve İskandinav şiirinde yaygındır.'),
  ('Eski İngiliz şiirinin ritmini belirleyen en önemli özellik hangisidir?', 'Dize içinde aynı ünsüzle başlayan sözcüklerin tekrarı', ['Dizelerin sonunda aynı sesle biten uyak', 'Her dizede tam on hece bulunması', 'Dörtlüklerin çapraz kafiye düzeni içinde olması'], 'Eski İngilizce şiirde dizeler ortadaki bir duraklamayla ikiye bölünür ve vurgulu sözcüklerin baş sesleri aliterasyonla uyumlandırılır.'),
  ('Thomas Malory\'nin \'Le Morte d\'Arthur\' (Arthur\'un Ölümü) eseri hangi alanın düzyazı derlemesidir?', 'Kral Arthur ve Yuvarlak Masa şövalyelerinin öykülerinin', ['Hz. İsa\'nın yaşamı ve havarilerinin öyküleri', 'Haçlı seferlerinin ayrıntılı anlatısı', 'Londra krallarının soy ağacı ve yaşamları'], 'Malory, çeşitli Fransız ve İngiliz kaynaklardan derlediği Arthur öykülerini düzyazıyla birleştirmiştir; Caxton 1485\'te bastı.'),
  ('İngiltere\'ye ilk matbaayı getirip 1476\'da basım işine başlayan kişi kimdir?', 'William Caxton', ['Thomas Malory', 'John Wycliffe', 'Geoffrey Chaucer'], 'Caxton, Westminster\'da kurduğu matbaada Chaucer ve Malory gibi yazarların eserlerini bastı; yazılı dilin yerleşmesine katkıda bulundu.'),
  ('15. yüzyıl ahlak oyunu \'Everyman\'ın (Herkes) temel kurgusu nedir?', 'Herkes\'in ölüm karşısında yalnız iyi işleriyle kalması', ['Bir kralın saray entrikalarıyla düşüşü', 'Bir şövalyenin ejderha avı serüveni', 'Bir köylünün sürgündeki acı yılları'], 'Alegorik kişileştirmelerle dolu oyun, insanın ölüm karşısında dünyevi her şeyden ayrılıp yalnız yaptığı iyiliklerle kaldığını anlatır.'),
  ('Sir Philip Sidney\'in \'Astrophil ve Stella\' yapıtı hangi şiir türüne aittir?', 'Sone dizisi', ['Epik şiir', 'Pastoral oyun', 'Manzum fabl'], 'Aşk acısını işleyen yüz sekiz sonelik dizi, İngiliz Rönesans şiirinin sone geleneğini başlatan yapıtlardandır.'),
  ('Marlowe\'un İngiliz tiyatrosuna kazandırdığı ve \'güçlü dize\' diye övülen şiir biçimi hangisidir?', 'Blank verse, uyaksız iyamb', ['Serbest nazım (free verse), ölçüsüz dize', 'Kafiyeli dörtlük (quatrain), çapraz uyaklı', 'Halk baladı (ballad), türkü kıtalı'], 'Marlowe, blank verse\'ü sahne diline uygun güçlü ve etkileyici hâle getirerek Shakespeare\'e zemin hazırlamıştır.'),
  ('Ben Jonson\'ın \'Volpone\' oyununda Venedikli Volpone ile uşağı Mosca\'nın yaptığı şey nedir?', 'Ölüm numarası yapıp mirasçıları kandırmak', ['Gizli bir hazinenin peşine düşüp ada aramak', 'Krallıkta bir isyan çıkarıp tahtı devirmek', 'Bir manastıra çekilip dünyadan elini çekmek'], 'Oyun, açgözlülük yüzünden kandırılan miras avcılarını hicveder; Jonson\'ın \'mizaç komedisi\' anlayışının örneğidir.'),
  ('Jacobean dönemi tragedyalarının genel havası nasıl nitelendirilir?', 'Karanlık, çürümüş ve şiddet yüklü', ['Pastoral, neşeli ve çiçekli bir çevreli', 'Ahlakçı ve öğretici hafif komedilerden oluşan', 'Zaferleri öven coşkulu tarih oyunlarına dayalı'], 'John Webster\'in \'Malfi Düşesi\' gibi oyunlarında saray yozlaşması, entrika ve kanlı intikamlar öne çıkar.'),
  ('1611\'de yayımlanan \'Kral James İncili\' İngiliz diline hangi katkıyı yapmıştır?', 'Ortak yazı dilinin ritmini ve deyimlerini etkilemesi', ['Latince\'nin yeniden yaygın yazı dili olması', 'İngilizcenin yazı dili olmaktan çıkması', 'Yeni bir alfabenin kabul edilmesi'], 'Bu çeviri, günlük İngilizceye pek çok deyim kazandırdı ve sonraki yazarların üslubunu derinden etkiledi.'),
  ('İngiltere\'de 1642\'de tiyatroların kapatılmasına yol açan siyasi gelişme nedir?', 'Puritanların iktidarı ve iç savaş', ['Büyük Londra Yangını ve salgın', 'Rönesans akımının sona ermesi', 'Matbaanın tümüyle yasaklanması'], 'Puritanlar tiyatroyu ahlaksız saydı; 1660\'ta monarşinin dönüşüne kadar tiyatrolar kapalı kaldı.'),
  ('Othello\'da Iago\'nun en baskın karakter özelliği nedir?', 'Kinci, hesapçı ve ikiyüzlü bir entrikacı olması', ['Saf, aşırı güvenen ve kolay kandırılan bir âşık', 'Cesur, dürüst ve safça güvenen bir asker', 'Merhametli bir arkadaş olması'], 'Iago, dürüst görünüşünün ardında terfi edemediği için duyduğu kini kullanarak Othello\'yu yıkar.'),
  ('Othello\'nun trajik kusuru (hamartia) olarak en sık gösterilen özellik hangisidir?', 'Kıskançlığın akıl yerine geçmesi', ['Aşırı hırsın vicdanı bastırması', 'Aşırı gururun akla üstün gelmesi', 'Aşırı çekingenlik'], 'Othello, kanıt olmadan Iago\'ya inanıp karısını öldürür; pişmanlıkla kendini de öldürür.'),
  ('Kral Lear\'da Gloucester Kontu\'na yapılan en ağır cezai işkence hangisidir?', 'Gözlerinin çıkarılması', ['Elinin ve kolunun kesilmesi', 'Sürgün edilmesi', 'Dilinin kesilmesi'], 'Regan ve eşi Cornwall, Gloucester\'ı Lear\'a yardım ettiği için kör eder; olay oyunun en sarsıcı sahnelerinden biridir.'),
  ('Kral Lear\'ın Soytarı\'sı oyunda hangi işlevi görür?', 'Şaka perdesiyle Lear\'a gerçekleri söyleyen bilge', ['Lear\'ın düşmanlarına gizlice casusluk eder', 'Lear\'ın düşmanı Cornwall\'a gizlice haber taşıyan casus', 'Cordelia\'ya âşık olur'], 'Soytarı, Lear\'ın hatalarını ince alaylarla gösterir; fırtına sahnesinde de ona eşlik eder.'),
  ('Romeo ve Juliet\'te Juliet\'in ölmüş gibi görünmesini sağlayan planı kim önerir?', 'Rahip Laurence', ['Mercutio, Romeo\'nun arkadaşı', 'Paris', 'Tybalt'], 'Rahip Laurence\'ın uyku iksiri, Romeo\'ya haber ulaşmayınca ölümcül sonuca yol açar.'),
  ('Romeo ve Juliet\'te Romeo\'nun sürgün edilmesine yol açan olay nedir?', 'Juliet\'in kuzeni Tybalt\'ı öldürmesi', ['Paris\'i bir düelloda yaralaması', 'Capulet\'lerin sarayına baskın yapması', 'Mercutio\'nun evini yakması'], 'Mercutio\'nun ölümüne öfkelenen Romeo, Tybalt\'ı öldürür; Verona Prensi onu şehirden sürer.'),
  ('Hamlet\'te Ophelia\'nın ölümü nasıl gerçekleşir?', 'Sinirleri bozulup nehirde boğulur', ['Kendi eliyle zehir içerek ölür', 'Düelloda Laertes tarafından öldürülür', 'Kaleden atlar'], 'Babası Polonius\'un ölümünden sonra aklını yitiren Ophelia, çiçekler toplarken nehre düşer ve boğulur.'),
  ('Bir Yaz Gecesi Rüyası\'nda çiftlerin kafasını karıştıran büyü ne ile yapılır?', 'Sevgi iksiri taşıyan bir çiçeğin suyuyla', ['Gizli bir mektubun okunması ve gecenin aldatması', 'Zehirli bir elmayla', 'Maskeli balo ile'], 'Puck, Oberon\'un emrini yanlış anlayarak yanlış kişilerin gözüne iksir sürer.'),
  ('On İkinci Gece\'de Viola, Illyria\'da kendisini kimmiş gibi tanıtır?', 'Cesario adında bir erkek uşak', ['Bir keşiş kılığındaki genç rahip', 'Bir şövalye', 'Bir tüccar'], 'Gemi kazasından kurtulan Viola, erkek kılığına girerek Dük Orsino\'nun hizmetine girer; böylece karışıklıklar başlar.'),
  ('On İkinci Gece\'de Malvolio\'nun alay konusu olmasına yol açan hile nedir?', 'Sahte aşk mektubuna kanıp gülünç davranması', ['Parasını çalıp hapse atılması ve sürgün edilmesi', 'Zindana atılması', 'Sarayda kovulması'], 'Olivia\'nın kâhyası Malvolio, sahte mektuba inanarak kibirli bir tavırla gülünç duruma düşer.'),
  ('Venedik Taciri\'nde Bassanio\'nun Portia\'yı kazanmasını sağlayan sınav nedir?', 'Üç kutudan (altın, gümüş, kurşun) doğru olanı seçmek', ['Bir düello ve ardından zor bir bilmece çözmek', 'Kılıç ustalığını kanıtlamak için bir düello yapmak', 'Kuş avı yarışması'], 'Portia\'nın babasının koyduğu kurala göre doğru kutuyu seçen kişi onunla evlenir; Bassanio kurşun kutuyu seçer.'),
  ('Boşuna Heyecan (Much Ado About Nothing) komedisinde Beatrice ile Benedick arasındaki sözlü çekişme nasıl aşka dönüşür?', 'Hileli dedikoduyla birbirine âşık olmaları', ['İlk görüşte tutulup birkaç gün içinde evlenmeleri', 'Ailelerin düşmanlığı', 'Askerî rütbe rekabeti'], 'Arkadaşları, her birine diğerinin kendisine âşık olduğunu duyurur; böylece ikisi de duygularını kabul eder.'),
  ('Dört büyük Shakespeare tragedyası olarak anılan oyunlar hangileridir?', 'Hamlet, Othello, Kral Lear, Macbeth', ['Romeo ve Juliet, Julius Caesar, Coriolanus, Titus', 'Fırtına, Kış Masalı, Cymbeline, Pericles', 'Richard III, Henry V, Macbeth, Lear'], 'Bu dört oyun, A. C. Bradley\'nin \'Shakespeare Tragedyası\' kitabında incelenen büyük tragedyalardır.'),
  ('Shakespeare\'in ölümünden yedi yıl sonra 1623\'te yayımlanan ve 36 oyunu bir araya getiren kitaba ne ad verilir?', 'First Folio (İlk Folyo)', ['Globe Tiyatrosu Kitabı (Globe Book)', 'Londra Külliyatı', 'Stratford Defteri'], 'Dostları John Heminges ve Henry Condell, Shakespeare\'in oyunlarını derleyip yayımlayarak birçok eserin kaybolmasını önlemiştir.'),
  ('Shakespeare\'in sonelerinde ana hitap edilen iki figür hangileridir?', 'Güzel Genç Adam ve Esmer Kadın', ['Kral ve Kraliçe, saray çifti', 'Ozan ve Denizci, deniz kıyısı çifti', 'Asker ve Denizci'], '154 sonenin büyük bölümü genç bir adama, sonraki bölümü ise esmer bir sevgiliye seslenir.'),
  ('Milton\'ın \'Kaybolmuş Cennet\'inde Şeytan\'a atfedilen ünlü \'Cennette hizmet etmektense cehennemde hüküm sürmek yeğdir\' sözü neyi yansıtır?', 'Şeytan\'ın gururu ve boyun eğmeyişi', ['Şeytan\'ın yenilgiyi kabullenişi ve pişmanlığı', 'Cehennemin huzurlu bir yer olduğu', 'Melekler arasındaki uyum ve kardeşlik'], 'Milton\'ın Şeytan\'ı, yenilgisine rağmen otoriteye başkaldıran ve gurur dolu bir figürdür; romantik okurlar onu kahramanlaştırmıştır.'),
  ('Milton\'ın \'Areopagitica\' (1644) adlı yazısının savunduğu ilke nedir?', 'Basının ön denetimden kurtulması ve düşünce özgürlüğü', ['Kralın mutlak yetkisinin yasayla güvence altına alınması ve sansürün sıkılaşması', 'Latincenin tek yazı dili olması', 'Tiyatroların kapatılması'], 'Parlamentonun basın izni yasasına karşı yazılan bu nutuk, sansüre karşı düşünce özgürlüğünün klasik savunmalarından biridir.'),
  ('Marvell\'ın \'Çekingen Sevgiliye\' (To His Coy Mistress) şiirinin ana teması nedir?', 'Zaman kısa olduğundan sevgiliden gecikmeden aşkı kabullenmesini istemek', ['Savaşın acılarını ve vatan sevgisini öne çıkararak sevgiliden uzaklaşmak gerektiği', 'Dinî tövbenin gerekliliği', 'Doğanın güzelliği'], '\'Elimizde yeterince dünya ve zaman olsaydı\' diye başlayan şiir, carpe diem (anı yaşa) düşüncesinin klasik örneğidir.'),
  ('John Donne\'un \'Ölüm, gururlanma\' (Death, be not proud) dizesiyle başlayan soneti hangi anlayışı yansıtır?', 'Ölümün ölümsüz ruh karşısında güçsüz olduğu inancını', ['Ölümün güçlü ve yenilmez olduğu, insanın ona boyun eğdiği inancını', 'Ölümün sonsuz kazanç olduğunu', 'Ölümün kralların işi olduğunu'], 'Donne, ölümü kişileştirip onunla alay eder; sonda \'Ölüm, sen öleceksin\' diyerek dinî inancın zaferini anlatır.'),
  ('\'Hiç kimse bir ada değildir\' (No man is an island) sözü hangi yazarın metninde geçer?', 'John Donne', ['John Milton', 'Andrew Marvell', 'George Herbert'], 'Donne\'un \'Meditation XVII\' yazısında geçen bu söz, insanların birbirine bağlılığını anlatır; \'çan kimin için çalıyor\' ifadesi de aynı metindendir.'),
  ('Cavalier şairlerinin (Lovelace, Suckling) şiirlerinde hangi tutum öne çıkar?', 'Aşk, onur ve sadakat temaları ile hafif ve zarif bir ton', ['Ağır dinî kaygılar ve metafizik soyutlamalarla yüklü, karmaşık bir üslup', 'Halk ayaklanmaları', 'Doğa bilimine dayanan imgeler'], 'Kral I. Charles\'ı destekleyen saray şairleri, zarif, hafif ve aşk ağırlıklı kısa şiirler yazmıştır.'),
  ('Restorasyon komedisinin (\'comedy of manners\') başlıca konusu nedir?', 'Yüksek sosyetenin aşk, evlilik ve entrikalarının alaycı bir dille anlatılması', ['Köylülerin yoksulluğunun, sert bir dille ve acılı bir ağıt havasıyla dile getirilmesi', 'Dinî mucizeler', 'Antik savaş kahramanları'], '1660 sonrası saray ve çevresi için yazılan komediler, zekâ oyunları ve toplumsal ikiyüzlülüğü sergiler.'),
  ('Aphra Behn\'in İngiliz yazın tarihindeki yeri nedir?', 'Geçimini yazarlıkla sağlayan ilk profesyonel kadın yazarlardan biri olması', ['İlk Poet Laureate unvanını alıp saray şairliği yapan yazar olması, kralın emriyle', 'Londra\'da ilk matbaayı kurması', 'Parlamentoya seçilen ilk kadın olması'], 'Behn, Restorasyon döneminde oyun ve roman yazarak yaşadı; \'Oroonoko\' adlı anlatısı ilk köleliğe karşı tutumlu eserlerden sayılır.'),
  ('Samuel Pepys\'in günlüğü hangi olayları çağdaş gözle belgeleyen bir kaynak olarak değerlidir?', '1660\'lardaki salgın ve Büyük Londra Yangını', ['Napolyon Savaşları\'nın Londra\'ya yansıması ve ardından gelen kıtlık yılları', 'Haçlı seferlerinin Londra\'ya yansıması', 'Sanayi Devrimi'], 'Pepys, günlüğünü stenografiyle tutarak Londra\'daki veba ve yangını ayrıntılı kaydetti.'),
  ('John Dryden\'ın \'Absalom ve Achitophel\' eseri hangi türdedir?', 'Siyasi hiciv şiiri', ['Dinî ağıtlar ve yas töreni şiirleri', 'Pastoral oyun', 'Seyahat günlüğü'], 'Eser, İncil\'deki bir öyküyü örtü yaparak kral II. Charles dönemindeki siyasi çekişmeleri hicveder.'),
  ('Dryden\'ın \'Her Şey Aşk İçin\' (All for Love) oyunu hangi Shakespeare oyunu ile aynı hikâyeyi işler?', 'Antonius ve Kleopatra', ['Romeo ve Juliet, Verona\'daki aşk', 'Macbeth', 'Hamlet'], 'Dryden, aynı öyküyü blank verse ile ve neoklasik kurallara uygun biçimde yeniden yazmıştır.'),
  ('Alexander Pope\'un \'Buklenin Çalınması\' (The Rape of the Lock) şiiri hangi türdedir?', 'Alay yollu destan', ['Ciddi bir ağıt (elegy), yas dilli', 'Ahlak oyunu', 'Seyahat anlatısı'], 'Pope, bir kıskıvrak bukle çalınması olayını destan diliyle anlatarak yüksek sosyetenin önemsiz tutkularını alaya alır.'),
  ('Pope\'un \'Eleştiri Üzerine Deneme\' eserinde yer alan \'Yanılmak insanidir, bağışlamak ilahi\' sözünün anlamı nedir?', 'İnsanın hata yapabileceği, bağışlamanın üstün bir erdem olduğu', ['Hata yapmanın ayıp, bağışlamanın ise gereksiz olduğu', 'Hatanın hiçbir şekilde bağışlanamaz olduğu', 'Bağışlamanın zayıflık sayıldığı'], 'Pope bu kuplede hata yapmayı insan, bağışlamayı ise tanrısal bir nitelik sayar.'),
  ('Pope\'un eserlerinde sıkça kullandığı nazım biçimi hangisidir?', 'Kahramanlık beyiti', ['Serbest nazım (free verse), ölçüsüz ve uyaksız bir biçim', 'Terza rima', 'Spenser kıtası'], 'Beşli iyamb ölçülü, çift uyaklı beyitler, Augustan şiirin ölçü ve denge anlayışını yansıtır.'),
  ('Addison ve Steele\'in \'The Spectator\' gibi yayınlarında geliştirilen tür nedir?', 'Süreli yayın denemesi', ['Kahramanlık destanı (epic poem), uzun, ciddi ve dizeli bir anlatı', 'Tarihî tragedya', 'Gotik roman'], 'Kahvehane ve gündelik yaşam üzerine kısa, öğretici ve zarif denemeler orta sınıf okurlar için yazılmıştır.'),
  ('Samuel Johnson\'ın 1755\'te yayımlanan İngilizce Sözlüğü neden dönüm noktası sayılır?', 'Tek kişinin yıllarca çalışıp örnek cümlelerle hazırladığı ilk büyük sözlük olması', ['Sözlüğün Latince yazılmış olması', 'Kral görevlendirmesiyle hazırlanan, yalnızca Latince açıklamalı bir sözlük olması', 'Yalnız şiir sözcüklerini içermesi'], 'Johnson, sözcüklerin anlamlarını edebî eserlerden aldığı alıntılarla açıkladı.'),
  ('James Boswell\'in \'Johnson\'ın Yaşamı\' kitabı neden önemlidir?', 'Modern biyografi türünün ilk büyük başyapıtlarından olması', ['İlk İngilizce şiir antolojisi olarak sayılan, çeviri ağırlıklı bir derleme', 'İlk polisiye roman olması', 'İlk seyahat rehberi olması'], 'Boswell, Johnson\'ın günlük konuşmalarını ve yaşamını ayrıntılı kaydederek biyografi türünü değiştirdi.'),
  ('Sheridan\'ın \'Rakipler\' (The Rivals) oyunundaki Bayan Malaprop adından hangi kavram doğmuştur?', 'Sözcükleri yanlış ama komik biçimde karıştırma', ['Sessiz kalıp hiç konuşmamayı seçmek ve bunun üstünden yanlış anlaşılmak', 'Şiirle konuşma', 'Sessizce oyunculuk'], 'Bayan Malaprop \'allegory\' yerine \'alligator\' gibi benzer sesli sözcükleri karıştırır.'),
  ('Thomas Gray\'in \'Bir Köy Mezarlığında Yazılmış Ağıt\' şiiri hangi konuyu işler?', 'Yoksul ve adsız köylülerin ölümü ve unutulmuş yeteneklerin yazgısı', ['Kralların zaferlerinin ve saraylı komutanların gösterişli ölümlerinin anlatılması, övgüyle', 'Şövalyelerin savaşları', 'Denizcilerin yolculukları'], 'Gray, gün batımında bir mezarlıkta adsız insanların yaşamını düşünür; eser, sentimental ve ağıt şiirinin klasiğidir.'),
  ('Samuel Richardson\'ın \'Pamela\' ve \'Clarissa\' romanları hangi anlatı biçimiyle yazılmıştır?', 'Mektup biçimi', ['Kronik biçimi', 'Manzum anlatı biçimi', 'Günlük ve harita notları biçimi'], 'Richardson, kahramanların mektuplarıyla iç dünyalarını ve olayları aktaran mektup romanının İngiltere\'deki öncüsüdür.'),
  ('Fielding\'in \'Tom Jones\' romanında başkarakter Tom\'un yaşamı nasıl nitelendirilir?', 'Yetim bir gencin yanlışlarla dolu serüvenlerle olgunlaşması', ['Bir kralın saray yaşamı', 'Zengin bir soyluya hizmet eden uşağın saray entrikalarında yükselmesi ve evliliği', 'Bir rahibin çilesi'], 'Bulunmuş çocuk Tom, çapkın ve cömert bir gençtir; roman serüven, komedi ve toplum tablosunu birleştirir.'),
  ('Defoe\'nun \'Moll Flanders\' romanı nasıl bir yaşam öyküsü anlatır?', 'Yoksulluk ve suç içinde ayakta kalmaya çalışan kadının serüvenlerini', ['Saray hayatında büyüyen soylu kadının yolculuklarını ve ahlaki hayat dersleri aldığını', 'Bir gemici subayının seferini', 'Bir şairin ruhsal bunalımını'], 'Moll, hırsızlık, evlilik ve sürgün arasında savrulur; roman gerçekçi bir ayrıntıyla anlatılır.'),
  ('Swift\'in \'Alçakgönüllü Bir Öneri\' adlı metninde öne sürdüğü sözde öneri nedir?', 'Yoksul İrlandalı çocukların yiyecek olarak satılması', ['Yoksulların başka bir ülkeye sürülmesi ve ağır vergilerle ezilmesi', 'Vergilerin kaldırılması', 'Kilisenin topraklarının dağıtılması'], 'Swift, soğukkanlı bir dille iğrenç bir öneri sunarak İrlanda\'daki yoksulluğa kayıtsızlığı alaya alır.'),
  ('Jane Austen\'ın romanlarını yazarının adı olmadan yayımlatmasında kullandığı ifade neydir?', '\'Bir Hanım Tarafından\'', ['\'Bir Gezgin Tarafından\' (By a Traveller), seyahat anlatısı gibi', '\'Bir Rahip Tarafından\'', '\'Bir Asker Tarafından\''], 'Austen, döneminin kadın yazarlara bakışı nedeniyle ilk romanlarını bu ifadeyle anonim yayımladı.'),
  ('Austen\'ın \'Emma\' romanında Emma Woodhouse\'un temel kusuru nedir?', 'Başkalarının evliliklerini kendi kafasına göre ayarlamaya kalkması', ['Mal sahibi olmak için zengin biriyle evlenmeye can atması ve para peşinde koşması', 'Dinî bağnazlık', 'Hırsızlık yapması'], 'Emma, kendi duygularını bile yanlış anlayarak çevresindekilerin aşklarına karışır ve hatalar yapar.'),
  ('Austen\'ın \'Akıl ve Duygu\' romanındaki iki kız kardeş hangileridir?', 'Elinor ve Marianne', ['Jane ve Elizabeth Bennet, komşu malikânenin kızları', 'Emma ve Harriet', 'Fanny ve Susan'], 'Elinor aklı, Marianne duyguyu temsil eder; roman bu iki yaklaşımın evlilik ve aşk karşısındaki sonuçlarını sınar.'),
  ('Austen\'ın \'Northanger Manastırı\' romanı hangi türü alaya alır?', 'Gotik romanı', ['Pikaresk romanı', 'Şövalye romansını', 'Pastoral şiiri'], 'Gotik romanlara kapılan Catherine Morland, gerçek hayatta da korkunç bir sır olduğuna inanır; ama gerçek olaylar sıradandır.'),
  ('Austen\'ın \'İkna\' (Persuasion) romanında Anne Elliot\'ın geçmişte reddettiği, sonradan yeniden karşılaştığı kişi kimdir?', 'Kaptan Wentworth', ['Albay Brandon, sakin ve yaşlı bir subay', 'Bay Knightley', 'Bay Elton'], 'Anne, yıllar önce arkadaşlarının telkiniyle Wentworth\'u reddetmiştir; roman ikinci bir şansı anlatır.'),
  ('Mary Shelley, Frankenstein\'ı hangi koşullarda yazmaya başlamıştır?', '1816\'da Cenevre Gölü kıyısında Byron\'ın önerdiği hayalet öyküsü yarışında', ['1816\'da Venedik\'te bir karnaval gecesinde kurulan satranç turnuvasında verilen sözle', 'Savaş cephesinde', 'Gemi yolculuğunda'], 'Byron, Percy Shelley ve Polidori ile geçirdiği yağmurlu yaz sırasında korku öyküsü yazma önerisi eserin doğuşuna yol açtı.'),
  ('Frankenstein\'ın alt başlığı \'Modern Prometheus\' neyi akla getirir?', 'İnsanlara ateşi çalarak veren titan gibi, doğaya aşırı müdahale eden bilimci', ['Tanrıların kralı Zeus\'un oğlu gibi, savaşta yenilmez kalan şövalyeyi ve onun zaferini', 'Odysseus\'un yolculuğu', 'Sisifos\'un kayası'], 'Prometheus mitosu, bilgiyi sınırı aşarak kullanmanın bedelini ima eder; Victor yarattığı yaratığın sorumluluğunu taşıyamaz.'),
  ('Charlotte Brontë\'nin \'Jane Eyre\' romanında Rochester\'ın evlenmesini engelleyen sır nedir?', 'Evin tavan arasında yaşayan deli karısı Bertha Mason', ['Evin bodrumunda gizlenmiş gizli bir çocuğu ve onun bakıcısı olan hizmetçiyi', 'Borçları', 'Kardeşi ile olan davası'], 'Düğün töreninde ortaya çıkan gerçek, Jane\'in Thornfield Hall\'dan ayrılmasına neden olur.'),
  ('Jane Eyre\'in çocukluk ve ilk gençlik yıllarında okuduğu, sert koşulların hâkim olduğu yatılı okul hangisidir?', 'Lowood', ['Thornfield', 'Marsh End', 'Gateshead'], 'Lowood, Jane\'in hem arkadaşı Helen Burns\'ü kaybettiği hem de yetiştiği zorlu bir kurumdur.'),
  ('Uğultulu Tepeler\'de Heathcliff\'in intikamına yol açan temel olay nedir?', 'Catherine\'in zenginlik için Edgar Linton\'ı seçmesi ve küçük düşürülmesi', ['Savaşta yenilip memleketten sürülmesi, mirasını yitirmesi ve ailesinin dağılması', 'Mirasını kaybetmesi', 'Adaya sürülmesi'], 'Heathcliff, aşağılanmış ve terk edilmiş hissedince Earnshaw ve Linton ailelerinden intikam almak için yıllarca planlar yapar.'),
  ('Dickens\'ın \'Büyük Umutlar\' romanında Pip\'in gizli hayırseveri olduğu ortaya çıkan kişi kimdir?', 'Mahkûm Magwitch', ['Havisham, yaşlı kadın ve bekâr hanımefendi', 'Jaggers, tanınmış Londralı avukat', 'Joe, dürüst demirci ve eniştesi'], 'Pip, serveti Bayan Havisham\'dan sandığı halde, bir zamanlar bataklıkta yardım ettiği kaçak mahkûmdan gelen para olduğunu öğrenir.'),
  ('Büyük Umutlar\'da Bayan Havisham\'ın evinde zamanı durdurmuş olması neyi simgeler?', 'Terk edilmenin acısına saplanıp kalmayı', ['Hükümdarlığın sürekliliğini', 'Mutfağın temizliğini', 'Mevsimlerin değişmesini'], 'Düğün günü terk edilen Havisham, saatleri o ana durdurur ve gelinliğiyle çürüyen pastanın yanında yaşar.'),
  ('Dickens\'ın \'David Copperfield\' romanında kötü, ikiyüzlü ve alçakgönüllü görünen kâtip kimdir?', 'Uriah Heep', ['Wilkins Micawber, hep umutlu kişi', 'Bay Murdstone, sert üvey baba', 'Steerforth, çekici arkadaş'], 'Uriah Heep, \'çok alçakgönüllüyüm\' sözleriyle çevresini kandıran, yüzsüz bir çıkarcıdır.'),
  ('Dickens\'ın \'Zor Zamanlar\' romanında Bay Gradgrind\'in eğitim anlayışı neye dayanır?', 'Yalnızca olgulara ve ölçülebilir bilgiye', ['Hayal gücüne ve şiire', 'Dinî öğretilere', 'Doğa gezilerine'], '\'Yalnızca olgular isteriz\' diyen Gradgrind, hayal gücünü dışlayan eğitimiyle çocuklarını mutsuz eder; roman sanayi toplumunu eleştirir.'),
  ('\'İki Şehrin Hikâyesi\'nde Sydney Carton\'ın sonunda yaptığı fedakârlık nedir?', 'Charles Darnay\'in yerine giyotine gitmesi', ['Darnay\'i düelloda öldürmesi', 'Lucie ile evlenmesi', 'Paris\'ten ayrılması'], 'Carton, benzerlikleri sayesinde Darnay\'in yerine idam edilerek sevdiği kadın Lucie\'nin mutluluğunu sağlar.'),
  ('\'Kasvetli Ev\' (Bleak House) romanında bir ailenin varlığını yıllarca tüketen dava hangisidir?', 'Jarndyce ve Jarndyce', ['Dedlock ve Dedlock', 'Tulkinghorn ve Tulkinghorn', 'Esther ve Esther'], 'Dava, Chancery Mahkemesi\'nin yavaş işleyişini hicveder; sonunda tüm miras mahkeme masraflarında erir.'),
  ('Dickens\'ın \'Pickwick Kulübü\'nün Ölümsüz Anıları\' romanının yayımlanma biçimi ve sonucu nedir?', 'Aylık parçalar halinde basıldı ve büyük bir okur kitlesi yarattı', ['Tek ciltte basıldı, az satıldı', 'Tiyatro olarak sahnelendi, kapandı', 'Mektup halinde yayımlanıp unutuldu'], '1836\'da başlayan tefrika, Dickens\'ı genç yaşta ünlü yaptı; Sam Weller karakteri yayın sayısını artırdı.'),
  ('Thackeray\'in \'Vanity Fair\' romanında Becky Sharp\'ın temel özelliği nedir?', 'Toplumsal yükselme için zekâ ve hileye başvuran hırslı kadın olması', ['Saf ve fedakâr bir hizmetçi olması', 'Dindar bir rahibe olması', 'Savaşta ölen bir asker olması'], 'Becky, yoksulluktan kurtulup yüksek sosyeteye girmeyi başarır; roman toplumun gösterişçi dünyasını hicveder.'),
  ('Elizabeth Gaskell\'in \'Kuzey ve Güney\' romanı hangi toplumsal ayrışmayı işler?', 'Kuzey sanayi kenti ile Güney kırsalı arasında sınıf ve değer farkını', ['Kıta Avrupası ile Britanya\'yı', 'Kraliyet ile parlamentoyu', 'Yoksul ile kilise çıkarını'], 'Margaret Hale\'in Güney\'den Kuzey\'in sanayi kentine taşınması, işçi-patron çatışmasını ve sınıf önyargılarını görmesini sağlar.'),
  ('George Eliot\'ın gerçek adı nedir?', 'Mary Ann Evans', ['Marian Brontë', 'Jane Elliot', 'Amelia Collins'], 'Mary Ann Evans, ciddiye alınmak için erkek takma ad kullandı; \'Adam Bede\' ve \'Silas Marner\' gibi eserleri yazdı.'),
  ('George Eliot\'ın \'Silas Marner\' romanında Silas\'ın yeniden insanlarla bağ kurmasını sağlayan şey nedir?', 'Evine gelen yetim bir kız çocuğu', ['Bir miras', 'Eski dostunun dönüşü', 'Bir yolculuk'], 'Altınını kaybeden Silas, kapısına gelen küçük Eppie\'yi evlat edinir ve yaşama yeniden bağlanır.'),
  ('Wilkie Collins\'in \'Aytaşı\' (The Moonstone) romanı hangi türün öncü örneği sayılır?', 'Polisiye (dedektif) romanı', ['Gotik roman', 'Bilimkurgu', 'Pikaresk roman'], 'Çalınan elmas etrafında dönen kurgu, ipuçları ve çok anlatıcılı yapısıyla modern dedektif romanının öncüsüdür.'),
  ('Hardy\'nin \'Casterbridge Belediye Başkanı\' romanında Michael Henchard\'ın trajedisini başlatan olay nedir?', 'Sarhoşken karısı ile kızını bir tüccara satması', ['Bir yangın çıkarması', 'Bir kralı eleştirmesi', 'Bir tapu sahtekârlığı'], 'Henchard bir panayırda içkinin etkisiyle karısını satar; yıllar sonra bu suç hayatını yıkar.'),
  ('Hardy\'nin \'Kızgın Kalabalıktan Uzakta\' romanında çiftlik sahibi Bathsheba Everdene\'in en çok dikkat çeken özelliği nedir?', 'Bağımsızlığına düşkün, kendi çiftliğini yöneten kadın olması', ['Rahibe olarak yaşaması', 'Soylu eşiyle yaşaması', 'Şehirde öğretmenlik yapması'], 'Bathsheba, kendi kararlarıyla çiftliği yönetir ama aşk ilişkilerinde acı yanılgılar yaşar.'),
  ('Hardy\'nin \'Ünlü Jude\' (Jude the Obscure) romanı yayımlanınca aldığı sert tepkiler Hardy\'yi hangi karara götürdü?', 'Roman yazmayı bırakıp şiire yönelmeye', ['İngiltere\'yi terk etmeye', 'Eserlerini yakmaya', 'Siyasete atılmaya'], 'Evlilik ve din eleştirisi içeren roman \'Jude the Obscure\' çok eleştirildi; Hardy bundan sonra roman yazmadı.'),
  ('Tennyson\'ın \'In Memoriam A.H.H.\' şiiri kimin anısına yazılmıştır?', 'Arkadaşı Arthur Hallam', ['Kardeşi Charles', 'Karısı Emily', 'Kraliçe Victoria'], 'Genç yaşta ölen dostu Hallam için uzun yıllar boyunca yazılan şiir, ölüm, inanç ve bilim üzerine yoğun bir ağıttır.'),
  ('Tennyson\'ın \'Ulysses\' şiirinin son dizesindeki \'Çabalamak, aramak, bulmak ve boyun eğmemek\' sözü ne anlama gelir?', 'Yaşlılığa karşın yeni keşiflerden vazgeçmeme kararlılığını', ['Yorgunluğa boyun eğmeyi', 'Savaştan kaçışı', 'Evde kalma isteğini'], 'Yaşlı Ulysses, evinde oturmak yerine yeniden yola çıkmayı seçer; şiir Viktorya dönemi kararlılığının simgelerindendir.'),
  ('Robert Browning\'in \'Son Düşesim\' (My Last Duchess) şiiri hangi şiir türünün klasik örneğidir?', 'Dramatik monolog', ['Pastoral ağıt', 'Tarihî balad', 'Sone dizisi'], 'Dük, kendi sesiyle konuşurken karakterinin kıskanç ve acımasız yanını farkında olmadan ele verir.'),
  ('Elizabeth Barrett Browning\'in \'Portekizce Sonelerden\' dizisi neyi anlatır?', 'Kocası Robert\'a duyduğu aşkı', ['Ailesinin sürgünü', 'Savaşın acısını', 'Dinî kuşkularını'], '\'Seni nasıl severim? Say-sayayım\' diye başlayan sone, bu dizinin en ünlü örneğidir.'),
  ('Wilde\'ın hapishanede, Lord Alfred Douglas\'a yazdığı uzun mektubundan oluşan yapıt hangisidir?', 'De Profundis', ['Reading Zindanı Baladı', 'Dorian Gray\'in Portresi', 'Salome'], 'Wilde, 1895\'te iki yıl hapis cezasına çarptırıldı; De Profundis bu dönemde yazılan itiraf niteliğindeki mektuptur.'),
  ('Wilde\'ın \'Reading Zindanı Baladı\' şiirinde hangi durum merkezî yer tutar?', 'Hapishanede idam edilecek bir mahkûmun son günleri', ['Savaş sırasında cepheye gönderilmiş bir askerin mektupları ve yası', 'Köy düğünü', 'Savaşın sonu'], 'Şiir, Wilde\'ın tutukluluk dönemindeki tanıklığına dayanır ve cezaevi koşullarını eleştirir.'),
  ('Wilde\'ın \'Dorian Gray\'in Portresi\' önsözündeki \'Bütün sanat tamamen yararsızdır\' sözü hangi anlayışı yansıtır?', 'Estetizm (sanat için sanat)', ['Toplumcu gerçekçilik (sanat toplum içindir)', 'Natüralizm', 'Klasisizm'], 'Wilde, sanatın ahlaki ya da yararcı amaç taşımaması gerektiğini savunan estetizm akımının öncülerindendi.'),
  ('Wilde\'ın \'Lady Windermere\'in Yelpazesi\' komedisinin konusu hangisidir?', 'Toplumun gözünde namuslu görünenlerin sırlarının açığa çıkması', ['Kralın saray yaşamındaki entrikaların sahnelenmesi ve soylu aile çatışmaları', 'Bir savaş kahramanının dönüşü', 'Bir tarım festivali'], 'Oyun, Viktorya toplumunun ikiyüzlü ahlak anlayışını zekice repliklerle hicveder.'),
  ('Shaw\'un \'Azize Jeanne\' (Saint Joan) oyunu hangi tarihî kişiyi konu alır?', 'Jeanne d\'Arc', ['Kraliçe Elizabeth', 'Kleopatra', 'Katerina'], 'Oyun, 15. yüzyılda Fransız ordusunu yöneten genç kadının yargılanmasını ve yakılmasını işler.'),
  ('Kipling 1907\'de Nobel Edebiyat Ödülü\'nü aldığında hangi unvanı elde etmiştir?', 'Ödülü alan en genç yazar olması', ['Ödülü ikinci kez almış olması', 'Ödülü reddeden ilk yazar olması', 'Ödülü şiirle kazanan ilk kişi olması'], 'Kipling, 41 yaşında ödülü alarak Nobel Edebiyat Ödülü\'nün en genç sahibi oldu.'),
  ('Kipling\'in \'Eğer\' (If—) şiirinde seslenilen kişiye hangi öğüt verilir?', 'Zorluk karşısında soğukkanlı, onurlu ve kararlı olması', ['Yalnızca yenilgiden sonra yeniden intikam peşine düşmesi ve ordu kurması gerektiğini', 'Savaşa katılması', 'Tüccar olması'], '\'If—\', oğluna öğüt veren bir babanın ağzından yazılmış, karakter ve dayanıklılık üzerine bir şiirdir.'),
  ('Conrad\'ın \'Karanlığın Yüreği\' romanında Marlow\'un nehir yolculuğunda bulmaya çalıştığı kişi kimdir?', 'Kurtz', ['Jim', 'Nostromo', 'Razumov'], 'Marlow, Kongo\'nun içinde fildişi ticaretiyle ünlenen, vahşete savrulan Kurtz\'un peşine düşer; son sözü \'Dehşet! Dehşet!\' olur.'),
  ('Conrad\'ın \'Lord Jim\' romanında Jim\'in hayatını belirleyen temel olay nedir?', 'Batmakta olan bir gemiyi yolcularıyla bırakıp kaçması ve bunun yarattığı utanç', ['Dev bir hazine haritası bulup kıyıya çıkması ve korsanlarla savaşması sonucunda zenginleşmesi', 'Bir isyan çıkarması', 'Bir aşk yüzünden sürülmesi'], 'Jim, namus ve cesaret konusunda kendi gözünde yenilir; ömrünü bu lekeyi silmeye çalışarak geçirir.'),
  ('Joseph Conrad\'ın dil bakımından dikkat çeken özelliği nedir?', 'Anadili Lehçe olduğu halde eserlerini İngilizce yazması', ['Anadili Fransızca olduğu halde bütün eserlerini yalnızca Fransızca yazması', 'Hiç İngilizce yazmaması', 'Anadilinin Latince olması'], 'Józef Korzeniowski, genç yaşta denizci oldu ve İngilizceyi üçüncü dil olarak öğrenip büyük romanlar yazdı.'),
  ('Conan Doyle\'un \'Kızıl Dosya\' (A Study in Scarlet) hangi ünlü ikilinin ilk kez göründüğü hikâyedir?', 'Sherlock Holmes ve Dr. Watson', ['Poirot ve Hastings', 'Dupin ve anlatıcı', 'Marple ve Craddock'], '1887 tarihli hikâye, Holmes\'un Watson\'la tanışmasını ve ilk büyük vakasını anlatır.'),
  ('W. B. Yeats\'in \'İkinci Geliş\' (The Second Coming) şiirinde \'Her şey dağılır, merkez tutamaz\' dizesi hangi duyguyu yansıtır?', 'Birinci Dünya Savaşı sonrası düzenin çöküşü korkusunu', ['Doğanın güzelliğinin ve pastoral huzurun geri dönüşünü ve mutlu bir devri', 'Aşkın zaferini', 'Köy yaşamının huzurunu'], 'Yeats, savaş ve devrim sonrasında dünyanın çözülüşünü, yaklaşan kaotik bir çağ imgesiyle verir.'),
  ('Yeats\'in \'Bizans\'a Yolculuk\' (Sailing to Byzantium) şiirinde yaşlı şairin bulmak istediği şey nedir?', 'Sanatın ölümsüzlüğü', ['Sanatın geçiciliği ve unutulmaya mahkûm oluşu', 'Yeni bir aşk', 'Anavatan toprağı'], 'Yaşlılığın ve bedenin çürümesi karşısında şair, Bizans\'ın ölümsüz sanatına sığınmak ister.'),
  ('Yeats\'in sahne sanatlarına katkısı nedir?', 'Abbey Tiyatrosu\'nun kurucuları arasında yer alması', ['Londra\'daki Globe Tiyatrosu\'nu yeniden inşa edenlerin başında yer alması', 'Royal Opera\'yı yönetmesi', 'Broadway\'de oyun yazması'], 'Yeats, Lady Gregory ile birlikte Dublin\'de Abbey Tiyatrosu\'nu kurarak İrlanda ulusal tiyatrosunu yarattı.'),
  ('Joyce\'un \'Ulysses\' romanındaki Leopold Bloom ve Stephen Dedalus ilişkisi neyi çağrıştırır?', 'Odysseus ile Telemakhos\'un baba-oğul ilişkisini', ['Aeneas ile Dido\'nun trajik ve imkânsız aşk ilişkisini', 'Orestes ile Elektra\'yı', 'Hektor ile Andromak\'ı'], 'Roman, Homeros\'un Odysseia\'sının modern bir yeniden yorumu sayılır.'),
  ('Woolf\'un \'Orlando\' romanının kahramanı hangi olağanüstü özelliğe sahiptir?', 'Yüzyıllar boyunca yaşar ve bir noktada cinsiyet değiştirir', ['Hiç yaşlanmayıp yalnızca erkek kalır', 'Gezegenler arası yolculuk yapar', 'Gece ve gündüz yer değiştirir'], 'Orlando, Elizabeth döneminden 20. yüzyıla uzanır; roman cinsiyet ve kimlik temalarını alaycı bir biyografi biçiminde işler.'),
  ('Woolf\'un içinde yer aldığı Bloomsbury Grubu kimlerden oluşan bir çevredir?', 'Londra\'da bir araya gelen yazar, sanatçı ve düşünürlerden', ['Parlamento üyesi aristokratlardan oluşan, siyasi ve ticari amaçlı çevre', 'Askerlerden oluşan bir subay kulübünden', 'Din adamlarından'], 'Grup, Woolf, Forster, Keynes ve Lytton Strachey gibi isimleri içeren, sanat ve düşünceyi özgürleştirmeye yönelmiş bir çevreydi.'),
  ('D. H. Lawrence\'ın \'Lady Chatterley\'in Sevgilisi\' romanı 1960\'ta yayımlandığında hangi olayın odağı oldu?', 'Müstehcenlik gerekçesiyle açılan dava ve Penguin\'in beraati', ['Kitabın Nobel alması', 'Kralın kitabı kutlaması', 'Yazarın cezaevine girmesi'], 'İngiltere\'de Penguin Books yayınevi, romanı basarak mahkemede aklandı; bu karar edebiyatta özgürlük açısından dönüm noktası sayılır.'),
  ('Lawrence\'ın \'Gökkuşağı\' romanı 1915\'te neden toplatıldı?', 'Müstehcen bulunduğu gerekçesiyle', ['Kralı ve soylu ailesini hicvettiği gerekçesiyle ve siyasi sebeplerle', 'Askerî sırlar içerdiği için', 'Bilimkurgu içerdiği için'], 'Roman, ahlaksız bulunarak savaş yıllarında mahkeme kararıyla yok edildi; yazar bu durumdan derin biçimde etkilendi.'),
  ('E. M. Forster\'ın \'Howards End\' romanının epigrafı ve ana düşüncesi olarak bilinen söz hangisidir?', 'Yalnızca bağlantı kurun', ['Hiçbir şey için geç değil', 'Yaşamak savaşmaktır', 'Doğaya dönelim'], 'Roman, farklı sınıflara ait iki ailenin ilişkisi üzerinden ruhsal ve toplumsal bağlantının önemini vurgular.'),
  ('Forster\'ın \'Manzaralı Oda\' romanında Lucy Honeychurch\'ün gittiği İtalya yolculuğu neyi sağlar?', 'Toplumsal kalıplardan kurtulup kendi duygularını fark etmesini', ['Soylu bir aileyle evlenip taşradaki malikânesine yerleşmesini ve para kazanmasını', 'Donanma subayıyla kaçmasını', 'Din değiştirmesini'], 'Floransa gezisi, Lucy\'nin toplumsal beklentilerle kendi arzusu arasındaki çatışmayı görmesine yol açar.'),
  ('T. S. Eliot\'ın \'J. Alfred Prufrock\'un Aşk Şarkısı\' şiirinin kahramanı hangi ruh hâlini taşır?', 'Çekingen, kararsız ve toplum karşısında kendini yetersiz hisseden bir orta yaşlı adam', ['Cesur, kararlı ve kendinden emin bir komutan ve toplum karşısında hep kazanan bir lider', 'Neşeli bir gezgin', 'Öfkeli bir devrimci'], 'Prufrock, \'Kendimi cesaretlendirebilir miyim?\' diye sorarak eylemsizliğini ve kaygısını dile getirir.'),
  ('Wilfred Owen\'ın \'Dulce et Decorum Est\' şiirinde eleştirilen şey nedir?', 'Vatan için ölmenin tatlı ve onurlu olduğu şeklindeki savaş söyleminin yalan oluşu', ['Askerlerin ücretlerinin düşük olması ve cephede yeterli yiyecek verilmemesi gibi hakların ihlali', 'Savaş tazminatı', 'Donanma harcamalarının yüksekliği'], 'Şiir, zehirli gaz saldırısında boğulan bir askeri anlatarak \'eski yalan\' dediği propagandayı çürütür.'),
  ('Wilfred Owen ne zaman öldü?', 'Birinci Dünya Savaşı\'nın bitmesinden bir hafta kadar önce', ['Savaşın ilk ayında', 'Savaştan yıllar sonra bir hastalıktan', '1914\'te Gelibolu\'da'], 'Owen, Kasım 1918\'de, ateşkesten kısa süre önce cephede öldü; şiirlerinin çoğu ölümünden sonra yayımlandı.'),
  ('Rupert Brooke\'un \'Asker\' (The Soldier) şiirinde ölen askerin dile getirdiği düşünce nedir?', 'Öldüğü yabancı toprağın bir köşesinin sonsuza dek İngiltere olacağı', ['Savaşın çok acımasız olduğu, ölümün hiçbir anlamı bulunmadığı ve kralın yenildiği', 'Hükümetin sert biçimde eleştirilmesi', 'Düşmana duyulan kin'], 'Brooke, yurt sevgisini idealize eden bu sonesiyle savaşın ilk yıllarındaki duyguyu yansıtır.'),
  ('Robert Graves\'in \'Goodbye to All That\' kitabı hangi türdedir?', 'Otobiyografi', ['Roman', 'Tiyatro', 'Şiir çevirisi'], 'Graves, savaş yıllarını ve İngiliz toplumuyla kopuşunu anlatır; kitap Birinci Dünya Savaşı belgeselleri arasında önemlidir.'),
  ('Orwell\'in \'1984\' romanında Winston Smith\'in çalıştığı bakanlık hangisidir?', 'Hakikat Bakanlığı', ['Eğitim Bakanlığı', 'Sevgi Bakanlığı', 'Bolluk Bakanlığı'], 'Winston, geçmişi Parti\'nin çıkarlarına göre yeniden yazarak belgeleri değiştirir.'),
  ('1984\'te Winston\'ın en çok korktuğu şeyin bulunduğu yer neresidir?', '101 Numaralı Oda', ['Sevgi Bakanlığı\'nın çatısı', 'Barış Bakanlığı mahzeni', 'Kayıt Dairesi'], '101 Numaralı Oda\'da kişi en büyük korkusuyla yüzleştirilir; Winston için bu korku sıçanlardır.'),
  ('John Osborne\'un \'Öfkeyle Geriye Bak\' oyunu 1956\'da neyin simgesi oldu?', '\'Öfkeli genç adamlar\' kuşağının ve toplumsal hoşnutsuzluğun', ['Saray tiyatrosunun yenilenmesinin ve geleneksel kraliyet repertuvarının canlanışının', 'Savaş zaferinin kutlanmasının', 'Kral destanlarının dönüşünün'], 'Jimmy Porter karakteri, savaş sonrası sınıf sistemine ve konforlu orta sınıfa öfke duyan yeni bir kuşağı temsil etmiştir.'),
  ('Coleridge\'in \'Kubla Han\' şiirinin yarım kalmasının nedeni olarak anlatılan olay hangisidir?', 'Porlock\'tan gelen bir ziyaretçinin onu yazarken bölmesi', ['Şairin hapse girmesi ve kâğıtlarının Londra\'da müsadere edilmesi nedeniyle', 'Kâğıtların yanması', 'Yayıncının şiiri reddetmesi'], 'Coleridge, afyonun etkisiyle gördüğü rüyayı yazarken bir ziyaretçi tarafından kesilmiş ve dizeleri tamamlayamamıştır.'),
  ('Coleridge\'in \'Biographia Literaria\' eserinde şiir okurken gereken tutumu anlatan ünlü kavram hangisidir?', 'İnançsızlığın gönüllü olarak askıya alınması', ['Gerçeklik duygusunun tamamen reddedilmesi ve dış dünyanın yadsınması', 'Nesnel karşılık', 'Sembolik uyum'], 'Okur, doğaüstü olaylara inanıyormuş gibi davranarak anlatıya katılır.'),
  ('Wordsworth\'ün \'Giriş\' (The Prelude) adlı uzun şiiri hangi türdedir?', 'Şairin zihinsel gelişimini anlatan otobiyografik şiir', ['Kralın saray hayatını konu alan, tarihî olayları kronolojik anlatan uzun bir destan', 'Aşk balad dizisi', 'Dinî alegori'], 'Şiir, çocukluğu, doğayla ilişkisi ve gençlik yıllarındaki Fransız Devrimi etkisi üzerinden şairin ruhsal gelişimini anlatır.'),
  ('Blake\'in \'Kaplan\' (The Tyger) şiirinde kaplanın yaratıcısına yöneltilen temel soru nedir?', 'Hem kuzuyu hem de bu korkunç yaratığı aynı Tanrı mı yarattı?', ['Kaplan neden orman yaşıyor?', 'Orman neden her gece bu kadar karanlık ve ürkütücü bir yer olarak yaratılmıştır, yaratıcı kim', 'Ormanın sahibi kim?'], 'Şiir, \'Kuzuyu yaratan seni de mi yarattı?\' diye sorarak iyilik ve kötülüğün kaynağını sorgular.'),
  ('Robert Burns hangi dilde şiir yazdığı için İskoç ulusal şairi sayılır?', 'İskoç lehçesi', ['Galce, Gal halkının kadim dili, şiir geleneği', 'Latince', 'Fransızca'], 'Burns, \'Auld Lang Syne\' ve \'Bir Fareye\' gibi şiirlerini İskoç lehçesiyle yazdı; doğum günü 25 Ocak, \'Burns Gecesi\' olarak kutlanır.'),
  ('Shelley\'nin \'Batı Rüzgârına Ode\' şiirinin son dizesindeki \'Kış gelmişse, bahar çok uzak olabilir mi?\' sözü hangi umudu anlatır?', 'Zorlukların ardından yenilenmenin geleceği umudunu', ['Soğuğun kalıcılığını', 'Ölümün kaçınılmazlığını', 'Savaşın sürmesini'], 'Şair, rüzgâra kendisini de bir yaprak gibi sürüklemesini ve düşüncelerini dünyaya yaymasını diler; sonda umudun sesi duyulur.'),
  ('Shelley\'nin \'Adonais\' şiiri kimin ölümü üzerine yazılmış bir ağıttır?', 'John Keats', ['Lord Byron', 'Robert Burns', 'Samuel Coleridge'], 'Shelley, Keats\'in 1821\'de Roma\'da ölmesi üzerine bu ağıtı yazdı; Keats\'in eleştirmenlerce yıpratıldığını öne sürdü.'),
  ('Percy Shelley, 1822\'de nasıl ölmüştür?', 'İtalya açıklarında kayıkla gezerken fırtınada boğulmuştur', ['Savaşta cephede yaralanıp hastanede ölmüştür', 'Verem yüzünden ölmüştür', 'Hapishanede ölmüştür'], 'Shelley, tekneyle yaptığı bir gezide fırtınaya yakalanarak La Spezia körfezinde boğuldu; cesedi kıyıya vurunca yakıldı.'),
  ('Byron\'ın \'Çocuk Harold\'ın Hac Yolculuğu\' yayımlandığında şaire ne kazandırdı?', 'Bir gecede ünlü olma', ['Hapis cezası ve sürgüne gönderilme, şöhretle birlikte', 'Siyasi bir görev', 'Nobel ödülü'], 'Byron, kitabın başarısı üzerine \'bir sabah uyandım, kendimi ünlü buldum\' demiştir.'),
  ('Byron\'ın \'Don Juan\' eserinin tarzı hangisidir?', 'Hicivli, alaycı ve yarım kalmış destansı anlatı şiir', ['Ağıt biçiminde, dinî ve ciddi, bitmiş uzun bir trajedi', 'Pastoral ağıt', 'Tarih yıllığı'], 'Byron, efsanevi Don Juan\'ı bu kez kadınların peşinden koşan değil, onlar tarafından avlanan biri olarak anlatır; eser yarım kalmıştır.'),
  ('Keats\'in \'Sonbahara\' (To Autumn) şiiri mevsimi nasıl betimler?', 'Bolluğu ve olgunluğu, sis ve meyve dolu bir mevsim olarak', ['Soğuk ve ölü bir mevsim olarak', 'Savaşın mevsimi olarak', 'Aşkın başlangıcı olarak'], '\'Sisler ve tatlı olgunluk mevsimi\' diye başlayan şiir, doğanın zenginliğini ve geçip gitmesini birlikte anlatır.'),
  ('Walter Scott\'ın \'Ivanhoe\' romanında çatışan iki halk hangisidir?', 'Saksonlar ve Normanlar', ['İngilizler ve Fransızlar', 'Romalılar ve Keltler', 'Kuzeyliler ve Güneyliler'], 'Roman, 12. yüzyıl İngiltere\'sinde Saksonlarla Norman yönetimi arasındaki gerilimi anlatır; tarihî romanın öncü örneğidir.'),
  ('Mary Wollstonecraft\'ın 1792 tarihli \'Kadın Haklarının Gerekçesi\' eseri neyi savunur?', 'Kadınların erkekler gibi akılcı eğitim alması gerektiğini', ['Kadınların evde kalmasını', 'Kadınların oy kullanmasını yasaklamayı', 'Kadınların sanat yapmasını engellemeyi'], 'Wollstonecraft, kadınlardaki zayıflık görüntüsünün eğitimsizlikten kaynaklandığını ileri sürer; eser feminist düşüncenin ilk büyük metinlerindendir.'),
  ('Tom Stoppard\'ın \'Rosencrantz ve Guildenstern Öldü\' oyunu hangi eserin yan karakterlerine odaklanır?', 'Hamlet', ['Macbeth', 'Othello', 'Fırtına'], 'Oyun, Hamlet\'te küçük rolleri olan iki arkadaşın kaderlerini anlamaya çalıştıkları absürt bir bakış sunar.'),
  ('Racine\'in \'Phèdre\' tragedyasında Phèdre\'in yıkımına yol açan duygu nedir?', 'Üvey oğlu Hippolyte\'e duyduğu yasak tutku', ['Kocasına duyduğu kin', 'Tahta duyduğu hırs', 'Kardeşinin intikamı'], 'Phèdre, kendi iradesine karşın üvey oğluna tutulur; tutkusu yalan ve ölümlerle sonuçlanan trajik bir zincire dönüşür.'),
  ('Racine\'in \'Bérénice\' tragedyasının sonunda Titus ile Bérénice birbirinden nasıl ayrılır?', 'Devlet gereği, birbirlerini sevmelerine karşın ayrılırlar', ['Biri diğerini öldürür', 'Düello sonrası ayrılırlar', 'Bir salgın yüzünden ayrılırlar'], 'Roma imparatoru Titus, halkın yabancı kraliçeyi istememesi yüzünden onu uzaklaştırır; oyun aşk ile görev çatışmasının acısını anlatır.'),
  ('Descartes\'ın \'Yöntem Üzerine Konuşma\' (1637) eseri Fransız yazı dili açısından neden önemlidir?', 'Felsefi bir metnin Latince yerine Fransızca yazılması', ['İlk Fransızca roman olması', 'İlk Fransızca ansiklopedi olması', 'İlk manzum felsefe olması'], 'Descartes, bilgiyi geniş kitlelerin okuyabilmesi için Fransızca yazdı; \'Düşünüyorum, öyleyse varım\' ilkesi de bu metindedir.'),
  ('Orta Çağ Fransız edebiyatında \'Renart Romanı\' hangi türdendir?', 'Hayvanların konuştuğu, toplumu hicveden hikâyeler dizisi', ['Şövalye romansı', 'Dinî tiyatro', 'Tarih kroniği'], 'Tilki Renart, kurnazlığıyla güçlü kurt Isengrin\'i ve soyluları alt eder; seri, feodal düzenin alaycı bir yansımasıdır.'),
  ('Rabelais\'nin \'Pantagruel\' ve \'Gargantua\' romanlarının dil özelliği nedir?', 'Bolluk, abartı, argo ve sözcük oyunlarıyla dolu halk diline yakın anlatım', ['Yalnızca Latince', 'Sade ve kısa cümleler', 'Ağıt dili'], 'Rabelais, bitmek bilmeyen sayımlar, abartılı mizah ve sözcük yaratımlarıyla ortaçağ ciddiyetini alaya alır.'),
  ('Fonvizin\'in \'Ergen\' (Nedorosl) komedisi hangi toplumsal sorunu hicveder?', 'Soylu sınıfın cahilliğini ve serf sahiplerinin zorbalığını', ['Kentlerin kalabalığını', 'Ordunun yetersizliğini', 'Din adamlarının zenginliğini'], 'Bayan Prostakova ve oğlu Mitrofan, eğitimsiz ve zorba bir soylu aileyi temsil eder; oyun 18. yüzyıl Rus komedisinin başyapıtıdır.'),
  ('Aleksandr Herzen\'in \'Geçmiş ve Düşünceler\' eseri hangi türdedir?', 'Anı ve otobiyografik anlatı', ['Şiir', 'Tiyatro oyunu', 'Seyahat rehberi'], 'Herzen, Rusya\'dan sürgün edildikten sonra yazdığı bu eserde kendi yaşamını ve çağının siyasi, düşünsel mücadelelerini anlatır.'),
  ('Belinski\'nin Rus edebiyatındaki rolü nedir?', 'Gogol ve Dostoyevski gibi gerçekçi yazarları destekleyen etkili eleştirmen olması', ['İlk Rus romanını yazması', 'Çarın sansür memuru olması', 'Tiyatro kumpanyası kurması'], 'Belinski, edebiyatın toplumsal gerçekliği yansıtması gerektiğini savunarak Rus gerçekçiliğini yönlendirdi.'),
  ('Bulgakov\'un \'Köpek Yüreği\' öyküsünde Profesör Preobrajenski\'nin sokak köpeği Şarik üzerinde yaptığı ameliyatın sonucu ne olur?', 'Köpek, kaba ve küstah bir insana dönüşür', ['Köpek ölümsüzleşir ve kendi türüne liderlik eder', 'Köpek konuşmaya başlar ama zekâsını yitirir', 'Profesör genç bir adama dönüşür ve yaşlanmaz'], 'Ameliyat sonrası ortaya çıkan Şarikov, toplumsal yükselme hırsı taşıyan kaba bir tiptir; öykü, Sovyet düzeninde yapay biçimde \'yeni insan\' yaratma çabasının hicvi sayılır.'),
  ('Shakespeare\'in \'V. Henry\' oyunundaki Saint Crispin Günü konuşmasında kralın askerlerine seslendiği ifade nedir?', 'Birbirimize bağlı bir kardeşler topluluğu', ['Zafere kesin olarak inanan bir ordu, yenilmez kahramanlardan oluşan topluluk', 'Taht için yarışanlar', 'Deniz aşırı tüccarlar'], 'Kral Henry, Agincourt Savaşı öncesinde azınlıkta olan askerlerini birlikte savaşan kardeşler olarak anarak onlara cesaret verir.'),
  ('Shakespeare\'in \'III. Richard\' oyunundaki ünlü \'Bir at, bir at! Atım için krallığımı veririm!\' çığlığı hangi anda atılır?', 'Bosworth Savaşı\'nda atını yitiren Richard\'ın son çarpışmasında', ['Düğün gecesinde, sevincin ardından Londra Kulesi\'nde', 'Taç giyme töreninde', 'Gemiyle sürgüne giderken'], 'Richard, savaş alanında atını kaybedince çaresizce haykırır; hemen ardından öldürülür.'),
  ('Shakespeare\'in \'IV. Henry\' oyunlarında hem komik hem trajik bir figür olan şişman şövalye kimdir?', 'Sir John Falstaff', ['Sir Toby Belch, On İkinci Gece\'nin ağırlıklı kişisi', 'Bardolph', 'Polonius'], 'Falstaff, Prens Hal\'in dostu olan gürültücü, korkak ama zeki bir şövalyedir; oyunda kralın sorumluluğuyla eğlence dünyası karşıtlığını temsil eder.'),
  ('Shakespeare\'in 18. sonesi \'Seni bir yaz gününe benzetsem mi?\' diye başlayarak sonunda ne söyler?', 'Şiirin sevgiliyi ölümsüz kılacağını', ['Yazın kısa sürmesine rağmen sevgilinin güzelliğinin zamanla yitirilmesini', 'Sevgilinin ihanet ettiğini', 'Şairin öleceğini'], 'Sone, doğanın güzelliğinin geçici oluşuna karşın şiir sayesinde sevgilinin güzelliğinin yaşayacağını söyler.'),
  ('Philip Larkin\'in \'Bu Dize Bir Ayet Olsun\' (This Be The Verse) şiirinde ana düşünce nedir?', 'Ebeveynlerin çocuklarını kendi kusurlarıyla yaralaması', ['Çocukluğun mutlu bir dönem olduğu', 'Evliliğin kutsallığı', 'Eğitimin önemi'], 'Larkin, alaycı bir dille kuşaklar arasında aktarılan acının kaçınılmazlığını anlatır.'),
  ('William Golding\'in \'Sineklerin Tanrısı\' romanında Ralph ve Jack\'in liderlik anlayışları nasıl ayrılır?', 'Ralph düzen ve kurallar, Jack ise avcılık ve korku yoluyla yönetim ister', ['Ralph savaş ve silahlanmayı, Jack ise tam barış ve dinî ibadeti öne çıkarır, ikisi de rakiptir', 'İkisi de aynı yöntemi savunur', 'Ralph dini, Jack bilimi savunur'], 'Ralph barınak ve duman ateşi gibi düzeni kurmaya çalışırken Jack avcılara dayalı bir gücü yeğler.'),
  ('Graham Greene\'in \'Sessiz Amerikalı\' romanı hangi ülkede geçer?', 'Vietnam', ['Küba, Havana\'daki casusluk romanıdır', 'Meksika', 'Mısır'], 'Roman, Fransız sömürge dönemi sonunda Saygon\'da geçer ve Batılı müdahalenin ahlaki sonuçlarını sorgular.'),
  ('Saint-Exupéry\'nin \'İnsanların Toprağı\' kitabı hangi mesleğin deneyimine dayanır?', 'Posta pilotluğu', ['Deniz subaylığı, gemi komutanı', 'Gazetecilik', 'Hekimlik'], 'Yazar, çöl ve dağlarda geçirdiği uçuşlardan yola çıkarak insan yaşamının anlamı ve dayanışma üzerine düşünür.'),
  ('Paul Éluard\'ın içinde yer aldığı Gerçeküstücülük akımında yazarlar hangi yöntemi sık kullanır?', 'Otomatik yazı ve rüya imgelerine dayalı serbest çağrışım', ['Kafiye ve ölçüye sıkı bağlılık', 'Tarih belgelerine bağlı yazım', 'Dinî alegori'], 'Gerçeküstücüler, bilinçdışının akışına güvenerek mantık kurallarını bir kenara bırakan yazı denemeleri yaptı.'),
  ('Verlaine\'in 1873\'te Brüksel\'de Rimbaud\'ya ateş etmesinin ardından hangi sonuç doğdu?', 'Verlaine iki yıl hapis cezası aldı', ['Rimbaud ağır yaralanıp ömür boyu sakat kaldı', 'Rimbaud Fransa\'dan kovuldu', 'İkisi birlikte Afrika\'ya gitti'], 'Verlaine, Rimbaud\'nun ayrılma isteği üzerine silah çekip onu kolundan yaraladı; mahkeme onu hapse mahkûm etti ve ikili ilişkisi bitti.'),
  ('Apollinaire\'in \'Alcools\' kitabında şiirlerde dikkat çeken yenilik nedir?', 'Noktalama işaretlerinin tümüyle kaldırılması', ['Yalnızca Latince sözcüklerin kullanılması', 'Sadece beyit biçiminin seçilmesi', 'Resimlerle dolu yazılması'], '1913\'te yayımlanan kitapta Apollinaire noktalamayı kaldırarak dizelerin ritmini ve okuma akışını okurun yorumuna bıraktı.'),
  ('\'Kış Masalı\'nda heykel gibi görünen ve yıllar sonra canlanan kişi kimdir?', 'Hermione', ['Perdita, kızı olan genç çoban kızı', 'Paulina', 'Miranda'], 'Kral Leontes\'in kıskançlığı yüzünden kaybolan Hermione, onaltı yıl sonra heykel gibi karşılaşılır ve canlanır; oyun bağışlama ve yenilenme temasını işler.'),
  ('George Eliot\'ın \'Değirmen\' (The Mill on the Floss) romanının sonunda Maggie ve Tom\'un sonu nasıl olur?', 'Bir sel baskınında birbirlerine sarılarak boğulurlar', ['Savaşa gönderilip cephede kardeşiyle birlikte çarpışırken yaralanıp ardından kayık kazasında ölürler', 'Hastalıktan ölürler', 'Başka ülkeye giderler'], 'Küskün kardeşler, selde kayıkla birbirine ulaşır ve ölürler; roman kardeş sevgisi ve toplumsal baskı arasında sıkışmış Maggie\'yi anlatır.'),
  ('George Eliot\'ın \'Middlemarch\' romanında Dorothea Brooke\'un hatalı evlilik seçimi hangi kişiyle olur?', 'Yaşlı bilgin Casaubon', ['Genç doktor Lydgate, hayalci tıp araştırmacısı', 'Will Ladislaw', 'Sir James Chettam'], 'Dorothea, büyük bir \'Tüm Mitolojilerin Anahtarı\' yazdığına inandığı Casaubon\'u idealize eder; evlilik hayal kırıklığı olur.'),
  ('Hardy\'nin \'Yerliler\' (The Return of the Native) romanının geçtiği ve neredeyse bir karakter gibi işlenen mekân hangisidir?', 'Egdon Çorağı', ['Casterbridge Limanı, bir deniz kenarı kasabası', 'Stonehenge Ovası', 'Wessex Katedrali'], 'Kasvetli Egdon Heath, kahramanların yazgısını belirleyen bir güç gibi betimlenir; Eustacia Vye\'ın kaçma tutkusu orada bunalır.'),
  ('Orwell\'in \'Katalonya\'ya Selam\' kitabı hangi olayın tanıklığını içerir?', 'İspanya İç Savaşı sırasında Cumhuriyetçi cephede savaşması', ['II. Dünya Savaşı sırasında Normandiya çıkarmasına katılması ve tutsak düşmesi', 'Hindistan\'da sömürge görevi', 'Rusya\'daki 1917 Devrimi'], 'Orwell, POUM milisleri arasında savaştı; Komünist Parti\'nin diğer sol grupları bastırmasına tanık oldu.'),
  ('Orwell\'in \'Paris ve Londra\'da Beş Parasız\' kitabı hangi türdedir?', 'Yoksulluğu bizzat yaşayarak anlatan belgesel anlatı', ['Eski İngiliz kolonilerindeki mahkûm yaşamını ayrıntılı biçimde anlatan bir bilimkurgu romanı', 'Tarihî dram', 'Şiir derlemesi'], 'Orwell, iki kentte aşçı yardımcılığı ve evsizlik deneyimlerini anlatarak yoksulluğun gündelik yüzünü gösterir.'),
  ('William Golding hangi yıl Nobel Edebiyat Ödülü\'nü almıştır?', '1983', ['1954, Hemingway\'in Nobel aldığı yıl', '1969, Beckett\'in ödül aldığı yıl', '2001, yüzyılın ilk Nobel ödül yılı'], 'Golding, insanlığın karanlık yönünü işleyen alegorik romanlarıyla 1983\'te Nobel\'e değer görüldü.'),
  ('Fransız Aydınlanması\'nda \'philosophe\' (filozof) terimi kimleri anlatır?', 'Akıl ve eleştirel düşünceyle toplumu değiştirmeyi amaçlayan yazar ve düşünürleri', ['Yalnızca Sorbonne\'daki resmî profesörleri, saray için üstü örtülü yazan yazarları', 'Din adamlarını', 'Saray müzisyenlerini'], 'Voltaire, Diderot ve Rousseau gibi isimler, akıl ve özgürlük fikirlerini yazılarla yaymışlardır.'),
];
